import { SeededRandom, hashSectorKey } from './SeededRandom'
import { sectorCenter, type SectorBounds } from './SectorGrid'
import { RadialDensityProfile } from './RadialDensityProfile'
import type { AsteroidProfileName } from './AsteroidProfiles'
import { morphologyRanges, type LibraryCategory, type MorphologyRange } from './archetypes/ArchetypeLibrary'

/**
 * Финализирующая лавинная перемешка (fmix32 из MurmurHash3) поверх hashSectorKey.
 *
 * ЗАЧЕМ: сырой hashSectorKey % K даёт систематическое смещение до ~35% при K,
 * не являющемся степенью двойки (типичный случай — K=14 архетипов библиотеки:
 * 14 = 2×7). Замерено на 8000 инстансах по десятку сидов — отклонение
 * стабильно (не только для «неудачного» сида) вылезает за допуск ±30% из
 * спеки. Причина: младшие биты FNV-подобного hashSectorKey хорошо перемешаны
 * только по модулю степени двойки, но не по модулю 7/14. fmix32 добавляет ещё
 * один раунд xor-shift + умножения ИСКЛЮЧИТЕЛЬНО над уже готовым 32-битным
 * значением — источник детерминизма (hashSectorKey(seed, index, const)) не
 * меняется, rng-поток не трогается, меняется только качество распределения
 * остатка по archetypeCount.
 */
function fmix32(hIn: number): number {
  let h = hIn
  h ^= h >>> 16
  h = Math.imul(h, 0x85ebca6b)
  h ^= h >>> 13
  h = Math.imul(h, 0xc2b2ae35)
  h ^= h >>> 16
  return h >>> 0
}

/**
 * Номер архетипа для инстанса камня (детерминированная раскладка по K архетипам).
 *
 * ПОЧЕМУ хеш, а не rng-поток: номер архетипа не должен потреблять байты из
 * SeededRandom-потока генерации позиции/поворота/масштаба — иначе смена
 * archetypeCount (K) сдвигала бы весь rng-поток и меняла позиции всех камней
 * сектора. Хеш детерминирован по (seed, index) независимо от K и от порядка
 * вызовов rng, поэтому позиции камней стабильны при перетюнинге библиотеки
 * архетипов.
 */
function archetypeForInstance(seed: number, index: number, archetypeCount: number): number {
  return fmix32(hashSectorKey(seed, index, 0x9e37)) % archetypeCount
}

/**
 * Конфигурация генератора
 */
interface GeneratorConfig {
  /** Толщина кольца (вертикальный разброс по Y в local space) */
  thickness: number
  /** Минимальный масштаб экземпляра */
  minScale: number
  /** Максимальный масштаб экземпляра */
  maxScale: number
  /**
   * Показатель степени розыгрыша масштаба t = (u1·u2)^sizeExponent, u1,u2 ~ U(0,1).
   * Не задан или 1 — прежнее t = u1·u2 (смещение к мелким, побайтно как раньше).
   */
  sizeExponent?: number
  /**
   * Профиль породы — раскладка инстансов по архетипам с учётом размера (см.
   * pickArchetype): мелкие камни чаще осколки, крупные — слипшиеся формы.
   * Без профиля раскладка равновероятна по хешу (archetypeForInstance).
   */
  profile?: AsteroidProfileName
  /**
   * Позиции камней — ОТНОСИТЕЛЬНО центра сектора (см. sectorCenter), а не
   * абсолютные в системе кольца. Абсолютную позицию восстанавливает шейдер:
   * instanceOrigin + instanceMatrix[3].xyz (см. InstancePool.writeOrigins).
   * Нужно поясу: на десятках а.е. абсолютная позиция теряет в float32 сотни
   * километров. Кольца флаг не включают — их матрицы побайтно прежние.
   */
  relativeToSector?: boolean
  /**
   * Границы сектора несут собственную полосу по высоте (объёмная сетка).
   * false — высота разыгрывается по всей толщине треугольным законом, как у колец.
   */
  volumetric?: boolean
}

/**
 * Наклон весов морфологий по доле размера t ∈ [0, 1]: осколки (fragment)
 * убывают с размером 1.6 → 0.4, слипшиеся формы (rubble/binary/top) растут
 * зеркально 0.4 → 1.6, кратерный монолит без наклона. В реальной популяции
 * крупные тела — гравитационные агрегаты, мелкие — угловатые обломки.
 */
function sizeTilt(morphology: LibraryCategory, t: number): number {
  switch (morphology) {
    case 'fragment':
      return 1.6 - 1.2 * t
    case 'rubble':
    case 'binary':
    case 'top':
    case 'real':
      // Реальные модели — формы крупных тел (агрегаты, спутники): как слипшиеся
      return 0.4 + 1.2 * t
    default:
      return 1
  }
}

/**
 * Выбор архетипа по двум равномерным величинам и доле размера: u1 выбирает
 * морфологию по весам профиля × наклон размера (диапазоны с count 0 не
 * участвуют), u2 — равновероятный индекс внутри диапазона морфологии.
 * Чистая функция — детерминизм и распределение тестируются отдельно.
 */
function pickArchetype(u1: number, u2: number, sizeT: number, ranges: readonly MorphologyRange[]): number {
  const t = Math.min(Math.max(sizeT, 0), 1)
  let total = 0
  const weights: number[] = []
  for (const range of ranges) {
    const w = range.count > 0 ? ASTEROID_WEIGHT_EPS + sizeTilt(range.morphology, t) * range.count : 0
    weights.push(w)
    total += w
  }
  if (total <= 0) return 0

  let acc = 0
  for (let i = 0; i < ranges.length; i++) {
    acc += weights[i] / total
    if (u1 < acc || i === ranges.length - 1) {
      const range = ranges[i]
      if (range.count <= 0) continue
      return range.start + Math.min(range.count - 1, Math.floor(u2 * range.count))
    }
  }
  return 0
}

/**
 * Веса выбора морфологии — доля библиотеки (count) × наклон размера: доля уже
 * несёт веса профиля (см. morphologyCounts). Эпсилон держит ненулевой шанс у
 * категории с одним индексом при экстремальном наклоне.
 */
const ASTEROID_WEIGHT_EPS = 1e-6

/** Равномерная величина [0, 1) из хеша — вторая перемешка fmix32 поверх ключа */
function hashUnit(seed: number, index: number, salt: number): number {
  return (fmix32(hashSectorKey(seed, index, salt)) >>> 0) / 4294967296
}

/**
 * AsteroidGenerator — детерминированная процедурная генерация данных экземпляров.
 *
 * Для заданного seed и границ сектора генерирует массив 4×4 матриц трансформации.
 * Один и тот же seed + bounds + count всегда даёт одинаковый результат.
 *
 * Не создаёт Three.js объекты — только заполняет Float32Array.
 */
class AsteroidGenerator {
  private readonly config: GeneratorConfig

  /**
   * Радиальный профиль плотности (A-full importance sampling). null → радиус
   * равномерно по площади полосы. Ставится асинхронно (текстура кольца готова).
   */
  private densityProfile: RadialDensityProfile | null = null

  public constructor(config: GeneratorConfig) {
    this.config = config
  }

  /** Задать радиальный профиль: радиус камня семплится ∝ альфе (концентрация в колечках). */
  public setDensityProfile(profile: RadialDensityProfile | null): void {
    this.densityProfile = profile
  }

  /**
   * Генерирует упакованный массив матриц 4×4 (16 float на экземпляр).
   * Позиции задаются в полярных координатах внутри bounds, затем конвертируются в декартовы.
   * Результат в local space кольца (XZ-плоскость, Y — вертикальный разброс).
   *
   * Частный случай generateMatricesGrouped с одной группой (archetypeCount=1) —
   * поведение и rng-поток побитово идентичны прежней реализации.
   *
   * @param seed — детерминированный seed сектора
   * @param count — количество экземпляров для генерации
   * @param bounds — границы сектора в полярных координатах
   * @returns Float32Array длиной count * 16
   */
  public generateMatrices(seed: number, count: number, bounds: SectorBounds): Float32Array {
    return this.generateMatricesGrouped(seed, count, bounds, 1)[0]
  }

  /**
   * Раскладка инстансов сектора по архетипам библиотеки (индекс k на инстанс).
   *
   * Без профиля — равновероятный хеш archetypeForInstance (прежнее поведение).
   * С профилем — по размеру камня: доля размера t каждого инстанса читается
   * реплеем того же rng-потока, что у generateMatricesGrouped (тот же порядок
   * вызовов, отдельный экземпляр SeededRandom → поток матриц не сдвигается),
   * морфология выбирается по весам профиля × наклон размера, индекс внутри
   * морфологии — по хешу (см. pickArchetype). Мелкие камни чаще осколки,
   * крупные — слипшиеся формы, как в реальной популяции.
   */
  public archetypeAssignment(seed: number, count: number, archetypeCount: number): Int32Array {
    const archetypeOf = new Int32Array(count)
    // Flat billboard generation has one destination for every instance. Keep
    // the fresh zero-filled array; no hash or separate morphology RNG is needed.
    if (archetypeCount === 1) return archetypeOf
    const profile = this.config.profile
    if (!profile) {
      for (let i = 0; i < count; i++) archetypeOf[i] = archetypeForInstance(seed, i, archetypeCount)
      return archetypeOf
    }

    const ranges = morphologyRanges(profile, archetypeCount)
    const rng = new SeededRandom(seed)
    for (let i = 0; i < count; i++) {
      // Реплей потока generateMatricesGrouped: радиус (1), угол (1), высота (2),
      // повороты (3), затем t = next·next — доля размера, затем анизотропия (3)
      for (let d = 0; d < 7; d++) rng.next()
      const t = rng.next() * rng.next()
      for (let d = 0; d < 3; d++) rng.next()
      archetypeOf[i] = pickArchetype(hashUnit(seed, i, 0x9e37), hashUnit(seed, i, 0x7f4a), t, ranges)
    }
    return archetypeOf
  }

  /**
   * Генерирует матрицы инстансов и группирует их по номеру архетипа.
   *
   * Два прохода: сначала раскладка archetypeAssignment — под каждую группу
   * выделяется Float32Array нужной длины; затем обычный цикл генерации,
   * матрица пишется в буфер своей группы.
   *
   * Раскладка по архетипам не влияет на позиции и повороты камней: она либо
   * хеш, либо реплей rng-потока отдельным экземпляром.
   *
   * @param seed — детерминированный seed сектора
   * @param count — количество экземпляров для генерации
   * @param bounds — границы сектора в полярных координатах
   * @param archetypeCount — число архетипов K, на которые раскладываются камни
   * @param assignment — готовый результат archetypeAssignment для тех же seed,
   *   count, archetypeCount и профиля генератора; массив не изменяется и не сохраняется
   * @returns массив длиной archetypeCount; элемент k — Float32Array матриц камней архетипа k,
   *   в порядке возрастания исходного индекса инстанса i
   */
  public generateMatricesGrouped(
    seed: number,
    count: number,
    bounds: SectorBounds,
    archetypeCount: number,
    assignment?: Int32Array
  ): Float32Array[] {
    // Проход 1: раскладка по архетипам (см. archetypeAssignment) — на rng-поток
    // прохода 2 не влияет: без профиля это хеш, с профилем — реплей того же
    // потока отдельным экземпляром SeededRandom.
    const archetypeOf = assignment ?? this.archetypeAssignment(seed, count, archetypeCount)
    const groupCounts = new Array<number>(archetypeCount).fill(0)
    for (let i = 0; i < count; i++) groupCounts[archetypeOf[i]]++

    const groups: Float32Array[] = groupCounts.map((c) => new Float32Array(c * 16))
    const runningOffsets = new Array<number>(archetypeCount).fill(0)

    // Проход 2: ровно прежний цикл генерации — rng-поток не сдвинут ни на байт.
    const rng = new SeededRandom(seed)
    const { thickness, minScale, maxScale } = this.config
    // Не задан или 1 — прежнее t = u1·u2 побайтно; шейпинг применяется ПОСЛЕ
    // обоих rng.next(), поэтому реплей archetypeAssignment не сдвигается
    const sizeExponent = this.config.sizeExponent ?? 1

    const r1Sq = bounds.minRadius * bounds.minRadius
    const r2Sq = bounds.maxRadius * bounds.maxRadius
    const halfThickness = thickness * 0.5

    // Центр сектора для относительных позиций — один раз на сектор, в double.
    // Без флага не считаем вовсе: путь колец не платит за пару тригонометрий
    const relative = this.config.relativeToSector === true
    const center = relative ? sectorCenter(bounds) : null
    const centerX = center ? center.x : 0
    const centerZ = center ? center.z : 0
    const centerY = center ? center.y : 0
    const volumetric = this.config.volumetric === true

    for (let i = 0; i < count; i++) {
      // Позиция по радиусу: с профилем — importance sampling ∝ альфе (камни
      // концентрируются в колечках), иначе — равномерно по площади полосы.
      // Оба пути тратят ровно один rng.next() → детерминизм не сдвигается.
      const r = this.densityProfile
        ? this.densityProfile.sampleRadius(bounds.minRadius, bounds.maxRadius, rng.next())
        : Math.sqrt(rng.range(r1Sq, r2Sq))
      const theta = rng.range(bounds.minAngle, bounds.maxAngle)
      const x = Math.cos(theta) * r
      const z = Math.sin(theta) * r
      // Относительно центра сектора: центр — в double, вычитание до float32-записи
      const px: number = relative ? x - centerX : x
      const pz: number = relative ? z - centerZ : z
      // Внутри ячейки высота равномерна: профиль колонки задан числом камней в
      // ячейке (см. triangularMass). Два вызова rng в обеих ветках — поток
      // случайных чисел у колец не сдвигается ни на вызов
      const u = rng.next()
      const v = rng.next()
      const y = volumetric ? bounds.minY + u * (bounds.maxY - bounds.minY) - centerY : (u + v - 1) * halfThickness

      // Поворот: случайные углы Эйлера
      const rx = rng.next() * Math.PI * 2
      const ry = rng.next() * Math.PI * 2
      const rz = rng.next() * Math.PI * 2

      // Масштаб: квадратичное распределение (больше мелких) со степенным шейпингом
      const t = rng.next() * rng.next()
      const shaped = sizeExponent === 1 ? t : Math.pow(t, sizeExponent)
      const s = minScale + shaped * (maxScale - minScale)

      // Пер-осевая анизотропия поверх базового скаляра s: ФИКСИРОВАННО ровно
      // три вызова rng.next() — по одному на ось, строго в порядке x, y, z,
      // сразу после базового скаляра. Число вызовов не зависит ни от чего
      // (архетипа, толщины и т.п.) — этим сохраняется детерминизм всего
      // rng-потока (см. докблок над generateMatricesGrouped). Диапазон
      // капнут mix(0.8, 1.25, u) = 0.8 + 0.45·u: шейдер восстанавливает
      // нормали через mat3(instanceMatrix) БЕЗ inverse-transpose, и заметно
      // большая анизотропия начала бы искажать освещение (Global Constraint
      // спеки архетипов).
      const sx = s * (0.8 + 0.45 * rng.next())
      const sy = s * (0.8 + 0.45 * rng.next())
      const sz = s * (0.8 + 0.45 * rng.next())

      // Compose матрицы inline (избегаем создание Three.js объектов для скорости),
      // запись в буфер своей группы по бегущему офсету.
      const k = archetypeOf[i]
      const offset = runningOffsets[k]
      runningOffsets[k] = offset + 16
      this.composeMatrix(groups[k], offset, px, y, pz, rx, ry, rz, sx, sy, sz)
    }

    return groups
  }

  /**
   * Записывает матрицу compose(position, eulerRotation, perAxisScale) в Float32Array.
   * Вычисление rotation matrix из Euler angles (XYZ order) inline.
   * Column-major order (как Three.js Matrix4).
   *
   * Масштаб пер-осевой: каждая из трёх колонок умножается на свою компоненту,
   * трансляция масштабу не подлежит. Диапазон вызывающий код держит близким к
   * изотропному — шейдер восстанавливает нормали через mat3(instanceMatrix)
   * без inverse-transpose, и сильная анизотропия исказила бы освещение.
   */
  private composeMatrix(
    out: Float32Array,
    offset: number,
    px: number,
    py: number,
    pz: number,
    rx: number,
    ry: number,
    rz: number,
    sx: number,
    sy: number,
    sz: number
  ): void {
    const cosX = Math.cos(rx),
      sinX = Math.sin(rx)
    const cosY = Math.cos(ry),
      sinY = Math.sin(ry)
    const cosZ = Math.cos(rz),
      sinZ = Math.sin(rz)

    out[offset] = cosY * cosZ * sx
    out[offset + 1] = cosY * sinZ * sx
    out[offset + 2] = -sinY * sx
    out[offset + 3] = 0

    out[offset + 4] = (sinX * sinY * cosZ - cosX * sinZ) * sy
    out[offset + 5] = (sinX * sinY * sinZ + cosX * cosZ) * sy
    out[offset + 6] = sinX * cosY * sy
    out[offset + 7] = 0

    out[offset + 8] = (cosX * sinY * cosZ + sinX * sinZ) * sz
    out[offset + 9] = (cosX * sinY * sinZ - sinX * cosZ) * sz
    out[offset + 10] = cosX * cosY * sz
    out[offset + 11] = 0

    out[offset + 12] = px
    out[offset + 13] = py
    out[offset + 14] = pz
    out[offset + 15] = 1
  }
}

export { AsteroidGenerator, archetypeForInstance, pickArchetype }
export type { GeneratorConfig }

import { Frustum, Matrix4, Sphere, Vector3 } from 'three'
import { SectorGrid, SectorInfo, SectorBounds, sectorCenter } from './SectorGrid'
import { AsteroidGenerator } from './AsteroidGenerator'
import { InstancePool, LODLevel, Allocation } from './InstancePool'
import { advanceDetailMix, detailEndDistance } from './impostors/impostorDetail'

/**
 * Конфигурация LOD-порогов
 */
interface LODThresholds {
  /** Максимальное расстояние для L0 (реальная геометрия, обычный detail) */
  l0MaxDistance: number
  /** Максимальное расстояние для L1 (billboards) — дальше ничего не грузим */
  l1MaxDistance: number
  /**
   * Порог ВХОДА в Near (ближний тир повышенной детализации), по distClosest
   * (расстояние до БЛИЖАЙШЕЙ точки сектора, см. update()). Сектор входит в
   * Near, когда ещё не был в нём и distClosest опустился до этого порога.
   */
  nearEnterDistance: number
  /**
   * Порог ВЫХОДА из Near, по distClosest. ОБЯЗАН быть > nearEnterDistance —
   * гистерезис (зазор между порогами) не даёт сектору, чья дистанция
   * колеблется у границы, флипать LOD каждый кадр (стейтлес-порог осциллирует
   * → вечные кросс-фейды, см. update()).
   */
  nearExitDistance: number
}

/**
 * Уходящий LOD-тир во время кросс-фейда: гаснет к 0 параллельно с проявлением
 * нового, затем его аллокация освобождается.
 */
interface OutgoingLOD {
  lodLevel: LODLevel
  /** Geometry: до K суб-аллокаций (по одной на непустой архетип-стрим); Billboard: одна. */
  allocations: Allocation[]
  /** Число инстансов тира — снимок state.instanceCount на момент ухода в fade-out, для вычитания из used */
  instanceCount: number
  fade: number
}

/**
 * Состояние активного сектора
 */
interface SectorState {
  key: string
  info: SectorInfo
  lodLevel: LODLevel
  /** Geometry: до K суб-аллокаций (по одной на непустой архетип-стрим); Billboard: одна. */
  allocations: Allocation[]
  /** Число инстансов ТЕКУЩЕГО тира (state.allocations) — снимок для точного вычитания из used */
  instanceCount: number
  /** Текущее значение fade (0 = невидим, 1 = полностью виден) */
  fade: number
  /** Целевое значение fade */
  fadeTarget: number
  /** Непрерывный вес деталей, независимый от видимости сектора. */
  detailMix: number
  /** Помечен для удаления после завершения fade-out */
  pendingRemoval: boolean
  /** Уходящий тир во время кросс-фейда смены LOD (null вне перехода) */
  outgoing: OutgoingLOD | null
}

/**
 * SectorManager — управляет жизненным циклом активных секторов.
 *
 * Каждый кадр:
 * 1. Определяет какие секторы должны быть видны (на основе позиции камеры + frustum)
 * 2. Рассчитывает LOD-уровень для каждого (L0 Geometry / L1 Billboard)
 * 3. Активирует новые секторы (с бюджетом — не более N за кадр)
 * 4. Деактивирует ушедшие за пределы видимости
 * 5. Обрабатывает fade-переходы
 * 6. При смене LOD — переключает сектор между буферами
 */
class SectorManager {
  private grid: SectorGrid
  private generator: AsteroidGenerator
  private pool: InstancePool
  private thresholds: LODThresholds

  /** Активные секторы: key → state */
  private activeSectors: Map<string, SectorState> = new Map()

  /** Максимальное количество секторов, активируемых за один кадр */
  private readonly activationBudget: number

  /** Максимум живых экземпляров каскада; Infinity — без ограничения (кольца) */
  private readonly capacityShare: number
  /** Сумма занятых экземпляров по активным секторам каскада (включая уходящий тир кросс-фейда) */
  private used: number = 0
  /** Счётчик отказов активации/смены LOD из-за упора в capacityShare */
  private capacityFailures: number = 0

  /** Скорость fade (доля за секунду) — обратная величина fadeSeconds конструктора */
  private readonly fadeSpeed: number

  /**
   * Множитель плотности инстансов на сектор для каждого LOD.
   *
   * Множители ОБЯЗАНЫ совпадать. Генератор потребляет rng последовательно по
   * индексу инстанса, поэтому камни 0..N-1 при любом count одинаковы; лишний
   * хвост у билборда существовал бы только как импостор и на переходе в
   * геометрию исчезал бы без замены. Набивать плотность вдали дешёвыми
   * билбордами можно только гася надбавку по расстоянию ДО переключения тира.
   */
  private readonly lodDensityMultiplier = {
    [LODLevel.Geometry]: 1.0,
    [LODLevel.GeometryNear]: 1.0,
    [LODLevel.Billboard]: 1.0
  }

  // Reusable objects
  private readonly _frustum = new Frustum()
  private readonly _sphere = new Sphere()
  private readonly _worldCenter = new Vector3()
  private readonly _origin = new Vector3()

  /**
   * Плавающее начало системы (ССЫЛКА на FloatingOrigin.origin — обновляется
   * снаружи, мы читаем текущее значение). null — относительных координат нет:
   * матрицы абсолютны, атрибут instanceOrigin остаётся нулевым (кольца).
   */
  private readonly origin: Vector3 | null

  public constructor(
    grid: SectorGrid,
    generator: AsteroidGenerator,
    pool: InstancePool,
    thresholds: LODThresholds,
    origin: Vector3 | null = null,
    capacityShare: number = Infinity,
    activationBudget: number = 4,
    /** Длительность проявления сектора, секунды; 0.25 (дефолт) — прежнее поведение (fadeSpeed 4.0) */
    fadeSeconds: number = 0.25
  ) {
    if (thresholds.nearEnterDistance >= thresholds.nearExitDistance) {
      throw new Error(
        `SectorManager: nearEnterDistance (${thresholds.nearEnterDistance}) обязан быть < nearExitDistance ` +
          `(${thresholds.nearExitDistance}) — без зазора между порогами вход/выход осциллировали бы на границе.`
      )
    }

    this.grid = grid
    this.generator = generator
    this.pool = pool
    this.thresholds = thresholds
    this.origin = origin
    this.capacityShare = capacityShare
    this.activationBudget = activationBudget
    this.fadeSpeed = 1 / fadeSeconds
  }

  /** Сумма занятых экземпляров активных секторов каскада (для capacityShare) */
  public get usedInstances(): number {
    return this.used
  }

  /**
   * Записать во все инстансы аллокаций смещение сектора от плавающего начала
   * И порог полного затухания билборда СВОЕГО каскада (см.
   * InstancePool.writeMaxDistance) — оба атрибута общие для сектора, второй
   * пишется независимо от наличия плавающего начала (кольца/одиночный каскад
   * тоже получают его, но без USE_CASCADE_FADE_RADIUS шейдер его не читает).
   * Без плавающего начала (кольца) origin остаётся no-op: атрибут нулевой.
   */
  private writeSectorOrigins(allocations: Allocation[], bounds: SectorBounds): void {
    for (const a of allocations) {
      this.pool.writeMaxDistance(a.stream, a.offset, a.count, this.thresholds.l1MaxDistance)
    }

    const origin = this.origin
    if (!origin) return

    const center = sectorCenter(bounds)
    // Вычитание — в double, до float32-записи атрибута: и центр сектора, и
    // начало могут быть десятками а.е., а их разность мала. Y тоже участвует:
    // у объёмной сетки центр ячейки не в средней плоскости, а генератор
    // вычитает его из высоты камня (relativeToSector) — без origin.y камни
    // осели бы к нулю независимо от реальной высоты ячейки.
    this._origin.set(center.x - origin.x, center.y - origin.y, center.z - origin.z)
    for (const a of allocations) {
      this.pool.writeOrigins(a.stream, a.offset, a.count, this._origin)
    }
  }

  /**
   * Переезд плавающего начала: у КАЖДОЙ активной аллокации (включая уходящий
   * тир кросс-фейда — он ещё рисуется) origin пересчитывается от центра её
   * сектора. К моменту вызова FloatingOrigin.origin уже новый, поэтому счёт
   * идёт от абсолютного центра в double — ошибка не накапливается от переезда
   * к переезду, в отличие от вычитания сдвига из хранимого float32.
   *
   * @param shift — сдвиг начала; нулевой означает, что переезда не было
   */
  public rebaseOrigins(shift: Vector3): void {
    if (!this.origin || (shift.x === 0 && shift.z === 0)) return

    for (const [, state] of this.activeSectors) {
      this.writeSectorOrigins(state.allocations, state.info.bounds)
      if (state.outgoing) {
        this.writeSectorOrigins(state.outgoing.allocations, state.info.bounds)
      }
    }
  }

  /**
   * Аллоцировать и заполнить суб-аллокации Geometry-пути (обычный detail ИЛИ
   * Near, повышенный detail — обе раскладки по K архетипам идентичны,
   * различается только базовый индекс стрима).
   *
   * Счётчики групп считаются до аллокаций и без обращения к rng — иначе смена
   * K сдвигала бы позиции камней. Камень сохраняет свой архетип при смене
   * detail-тира, меняется только база стрима.
   *
   * Любой отказ откатывает уже выделенные суб-аллокации и возвращает null:
   * сектор не активируется, отказ виден через getPressureInfo().failures.
   */
  private allocateGeometryGroups(
    streamBase: number,
    seed: number,
    count: number,
    bounds: SectorBounds
  ): Allocation[] | null {
    const archetypeCount = this.pool.geometryStreamCount
    // Размер группы — по раскладке САМОГО генератора (с профилем породы она
    // идёт по морфологиям, не по равновероятному хешу): иначе группа длиннее
    // сгенерированного хвостом единичных матриц (тело масштаба 1 в начале
    // сектора), а короче — записью матриц в чужие слоты
    const assignment = this.generator.archetypeAssignment(seed, count, archetypeCount)
    const groupCounts = new Array<number>(archetypeCount).fill(0)
    for (let i = 0; i < count; i++) {
      groupCounts[assignment[i]]++
    }

    const allocations: Allocation[] = []
    for (let k = 0; k < archetypeCount; k++) {
      if (groupCounts[k] === 0) continue

      const allocation = this.pool.allocate(streamBase + k, groupCounts[k])
      if (!allocation) {
        for (const a of allocations) this.pool.release(a)
        return null
      }
      allocations.push(allocation)
    }

    // Повторно используем раскладку, по которой только что выделили группы.
    const groups = this.generator.generateMatricesGrouped(seed, count, bounds, archetypeCount, assignment)
    for (const allocation of allocations) {
      const k = allocation.stream - streamBase
      this.pool.writeMatrices(allocation.stream, allocation.offset, groups[k])
      // Стартуем невидимым — updateFades плавно поднимет fade к 1.
      this.pool.writeFade(allocation.stream, allocation.offset, allocation.count, 0.0)
    }

    this.writeSectorOrigins(allocations, bounds)

    return allocations
  }

  /**
   * Аллоцировать суб-аллокации для заданного LOD-уровня. Billboard — как
   * раньше, один стрим (pool.billboardStream), generateMatrices (не
   * группированный); Geometry/GeometryNear — раскладка по K архетипам (см.
   * allocateGeometryGroups), различается только базовый индекс стрима.
   */
  private allocateForLOD(lodLevel: LODLevel, seed: number, count: number, bounds: SectorBounds): Allocation[] | null {
    if (lodLevel === LODLevel.Geometry) {
      return this.allocateGeometryGroups(0, seed, count, bounds)
    }
    if (lodLevel === LODLevel.GeometryNear) {
      return this.allocateGeometryGroups(this.pool.nearStreamBase, seed, count, bounds)
    }

    const stream = this.pool.billboardStream
    const allocation = this.pool.allocate(stream, count)
    if (!allocation) return null

    const data = this.generator.generateMatrices(seed, count, bounds)
    this.pool.writeMatrices(stream, allocation.offset, data)
    if (this.pool.impostorAttributes) {
      this.pool.writeArchetypes(allocation, this.generator.archetypeAssignment(seed, count, this.pool.geometryStreamCount))
    }
    this.pool.writeFade(stream, allocation.offset, allocation.count, 0.0)
    this.writeSectorOrigins([allocation], bounds)

    return [allocation]
  }

  /**
   * Основной метод обновления. Вызывается каждый кадр.
   *
   * @param cameraAngle — угол камеры в полярных координатах (radians) в local space кольца
   * @param cameraRadius — расстояние камеры от центра кольца в local space
   * @param cameraY — высота камеры, ring-local Y. Обязательна: у плоской сетки
   * (volumetric false) не влияет на результат, но неявный ноль у объёмной молча
   * подставил бы среднюю плоскость вместо реальной высоты камеры.
   * @param viewProjectionMatrix — camera.projectionMatrix * camera.matrixWorldInverse
   * @param localToWorldMatrix — матрица трансформации системы (local → world)
   * @param delta — время с прошлого кадра (секунды)
   */
  public update(
    cameraAngle: number,
    cameraRadius: number,
    cameraY: number,
    viewProjectionMatrix: Matrix4,
    localToWorldMatrix: Matrix4,
    delta: number
  ): void {
    // 1. Подготовить frustum
    this._frustum.setFromProjectionMatrix(viewProjectionMatrix)

    // 2. Получить кандидатов из сетки
    const maxRange = this.thresholds.l1MaxDistance
    const candidates = this.grid.getSectorsInRange(cameraAngle, cameraRadius, cameraY, maxRange)

    // 3. Определить LOD и отфильтровать по frustum
    const desiredSectors = new Map<string, { info: SectorInfo; lod: LODLevel }>()

    const camX = Math.cos(cameraAngle) * cameraRadius
    const camZ = Math.sin(cameraAngle) * cameraRadius

    for (const info of candidates) {
      // A-lite: пустотные сектора (радиальный профиль дал вес ~0 → instanceCount 0)
      // не генерируем вовсе. Уже активный сектор, ставший пустотным (профиль
      // подгрузился), выпадет из desired → плавно погаснет.
      if (info.instanceCount <= 0) continue

      const dx = info.centerX - camX
      const dz = info.centerZ - camZ
      // Высота входит только у объёмной сетки: у колец метрика двумерная, как была
      const dy = this.grid.volumetric ? info.centerY - cameraY : 0
      const dist = Math.sqrt(dx * dx + dz * dz + dy * dy)
      // Расстояние до БЛИЖАЙШЕЙ точки сектора, не до центра: info.boundingRadius
      // (полудиагональ ячейки) обычно уже сравним с разумным порогом входа в
      // Near — порог по dist-до-центра в такой геометрии никогда бы не
      // сработал (подтверждено подкраской в дебаге). distClosest — грубая, но
      // достаточная оценка (сектор не сфера, но boundingRadius её описывает).
      const distClosest = Math.max(0, dist - info.boundingRadius)

      // Гистерезис входа/выхода в Near: сектор, УЖЕ находящийся в Near, остаётся
      // в нём пока distClosest <= nearExitDistance; иначе входит в Near только
      // при distClosest <= nearEnterDistance (порог входа < порог выхода —
      // проверено в конструкторе). Без зазора между порогами стейтлес-порог у
      // границы осциллировал бы каждый кадр → вечные кросс-фейды Near↔Geometry.
      const existingForLod = this.activeSectors.get(info.key)
      const alreadyNear = existingForLod?.lodLevel === LODLevel.GeometryNear && !existingForLod.pendingRemoval

      // Определить LOD (по возрастанию расстояния: Near → L0 → billboard)
      let lod: LODLevel
      if (alreadyNear && distClosest <= this.thresholds.nearExitDistance) {
        lod = LODLevel.GeometryNear
      } else if (!alreadyNear && distClosest <= this.thresholds.nearEnterDistance) {
        lod = LODLevel.GeometryNear
      } else if (dist <= this.thresholds.l0MaxDistance) {
        lod = LODLevel.Geometry
      } else if (dist <= this.thresholds.l1MaxDistance) {
        lod = LODLevel.Billboard
      } else {
        continue
      }

      // Frustum culling
      this._worldCenter.set(info.centerX, info.centerY, info.centerZ)
      this._worldCenter.applyMatrix4(localToWorldMatrix)
      this._sphere.set(this._worldCenter, info.boundingRadius)

      if (!this._frustum.intersectsSphere(this._sphere)) {
        continue
      }

      desiredSectors.set(info.key, { info, lod })
    }

    // 4. Diff: определить что активировать/деактивировать/переключить LOD
    const toActivate: { info: SectorInfo; lod: LODLevel }[] = []
    const toChangeLOD: { state: SectorState; newLOD: LODLevel; info: SectorInfo }[] = []

    for (const [key, desired] of desiredSectors) {
      const existing = this.activeSectors.get(key)
      if (!existing) {
        toActivate.push(desired)
      } else if (existing.lodLevel !== desired.lod && !existing.pendingRemoval) {
        toChangeLOD.push({ state: existing, newLOD: desired.lod, info: desired.info })
      } else if (existing.pendingRemoval) {
        existing.pendingRemoval = false
        existing.fadeTarget = 1.0
      }
    }

    // Секторы, которые больше не нужны → пометить для fade-out
    for (const [key, state] of this.activeSectors) {
      if (!desiredSectors.has(key) && !state.pendingRemoval) {
        state.pendingRemoval = true
        state.fadeTarget = 0.0
      }
    }

    // 5. Активация новых секторов (с бюджетом). Высота входит только у
    // объёмной сетки — та же оговорка, что и у метрики тира выше.
    toActivate.sort((a, b) => {
      const dyA = this.grid.volumetric ? a.info.centerY - cameraY : 0
      const dyB = this.grid.volumetric ? b.info.centerY - cameraY : 0
      const distA = (a.info.centerX - camX) ** 2 + (a.info.centerZ - camZ) ** 2 + dyA * dyA
      const distB = (b.info.centerX - camX) ** 2 + (b.info.centerZ - camZ) ** 2 + dyB * dyB
      return distA - distB
    })

    let activated = 0
    for (const { info, lod } of toActivate) {
      if (activated >= this.activationBudget) break
      // Упор в долю пула — дальше по списку сектора только дальше от камеры,
      // пробовать их бессмысленно, а счётчик отказов иначе считал бы кандидатов
      if (this.used >= this.capacityShare) {
        this.capacityFailures++
        break
      }
      if (this.activateSector(info, lod)) {
        activated++
      }
    }

    // 6. Смена LOD для существующих секторов — тем же бюджетом, что активация.
    // Каждый переход держит ОБА тира до конца кросс-фейда, поэтому массовый
    // свитч на проходе камеры вынес бы каскад далеко за его долю пула
    toChangeLOD.sort((a, b) => {
      const dyA = this.grid.volumetric ? a.info.centerY - cameraY : 0
      const dyB = this.grid.volumetric ? b.info.centerY - cameraY : 0
      const distA = (a.info.centerX - camX) ** 2 + (a.info.centerZ - camZ) ** 2 + dyA * dyA
      const distB = (b.info.centerX - camX) ** 2 + (b.info.centerZ - camZ) ** 2 + dyB * dyB
      return distA - distB
    })

    let switched = 0
    for (const { state, newLOD, info } of toChangeLOD) {
      if (switched >= this.activationBudget) break
      if (this.changeSectorLOD(state, newLOD, info)) {
        switched++
      }
    }

    // 7. Обновить fade и удалить завершённые fade-out
    this.updateFades(delta)
  }

  /**
   * Активировать новый сектор.
   */
  private activateSector(info: SectorInfo, lodLevel: LODLevel): boolean {
    const instanceCount = Math.max(1, Math.round(info.instanceCount * this.lodDensityMultiplier[lodLevel]))

    // Доля пула каскада — проверка ДО выделения, чтобы не трогать пул зря.
    if (this.used + instanceCount > this.capacityShare) {
      this.capacityFailures++
      return false
    }

    const allocations = this.allocateForLOD(lodLevel, info.seed, instanceCount, info.bounds)
    if (!allocations) {
      return false
    }
    this.used += instanceCount

    const state: SectorState = {
      key: info.key,
      info,
      lodLevel,
      allocations,
      instanceCount,
      fade: 0.0,
      fadeTarget: 1.0,
      detailMix: lodLevel === LODLevel.Billboard ? 0 : 1,
      pendingRemoval: false,
      outgoing: null
    }

    this.writeSectorDetails(state, allocations)

    this.activeSectors.set(info.key, state)
    return true
  }

  /**
   * Переключить сектор на другой LOD-уровень через кросс-фейд.
   *
   * Старый тир не освобождается сразу: он уходит в state.outgoing и гаснет к 0
   * параллельно с проявлением нового (с нуля) — оба рендерятся через дизер
   * одновременно, давая встречный кросс-фейд без резкого «щелчка».
   */
  private changeSectorLOD(state: SectorState, newLOD: LODLevel, info: SectorInfo): boolean {
    const instanceCount = Math.max(1, Math.round(info.instanceCount * this.lodDensityMultiplier[newLOD]))

    // Доля пула по УСТАНОВИВШЕЙСЯ стоимости: на время кросс-фейда сектор держит
    // оба тира, но проверять сумму нельзя — понижение тира, которое ёмкость
    // освобождает, само себя бы и запретило
    if (this.used - state.instanceCount + instanceCount > this.capacityShare) {
      this.capacityFailures++
      return false
    }

    const allocations = this.allocateForLOD(newLOD, info.seed, instanceCount, info.bounds)

    if (!allocations) {
      // Нет места под новый тир — оставляем текущий как есть (сектор не теряем).
      return false
    }

    // Текущий тир уводим в кросс-фейд-аут. Если предыдущий outgoing ещё жив
    // (быстрый повторный свитч) — освобождаем его целиком: держим максимум 2 тира.
    if (state.outgoing) {
      for (const a of state.outgoing.allocations) this.pool.release(a)
      this.used -= state.outgoing.instanceCount
    }
    state.outgoing = {
      lodLevel: state.lodLevel,
      allocations: state.allocations,
      instanceCount: state.instanceCount,
      fade: state.fade
    }

    // used держит ОБА тира на время кросс-фейда: старый (перешёл в outgoing,
    // уже учтён) не вычитается, новый прибавляется — снимется при release() outgoing.
    this.used += instanceCount
    state.lodLevel = newLOD
    state.allocations = allocations
    state.instanceCount = instanceCount
    // Новый тир проявляется с нуля — встречно уходящему (сумма покрытия ≈ 1).
    // fade=0 уже записан в буфер внутри allocateForLOD — повторной записи не требуется.
    state.fade = 0.0
    state.fadeTarget = 1.0
    this.writeSectorDetails(state, allocations)

    return true
  }

  private writeSectorDetails(state: SectorState, allocations: Allocation[]): void {
    const end = detailEndDistance(this.thresholds.l0MaxDistance, state.info.boundingRadius)
    for (const allocation of allocations) {
      this.pool.writeDetailEnd(allocation, end)
      this.pool.writeDetailMix(allocation, state.detailMix)
    }
  }

  /**
   * Обновить fade-анимации и удалить полностью погасшие секторы.
   */
  private updateFades(delta: number): void {
    const step = this.fadeSpeed * delta
    const toRemove: string[] = []

    for (const [key, state] of this.activeSectors) {
      const nextMix = advanceDetailMix(state.detailMix, state.lodLevel === LODLevel.Billboard ? 0 : 1, delta, this.fadeSpeed)
      if (nextMix !== state.detailMix) {
        state.detailMix = nextMix
        for (const allocation of state.allocations) this.pool.writeDetailMix(allocation, nextMix)
        for (const allocation of state.outgoing?.allocations ?? []) this.pool.writeDetailMix(allocation, nextMix)
      }
      if (state.fade !== state.fadeTarget) {
        if (state.fade < state.fadeTarget) {
          state.fade = Math.min(state.fade + step, state.fadeTarget)
        } else {
          state.fade = Math.max(state.fade - step, state.fadeTarget)
        }
        // fade изменился — залить новое значение в per-instance атрибут КАЖДОЙ
        // суб-аллокации сектора. Осевшие секторы (fade == fadeTarget) не трогаем.
        for (const a of state.allocations) {
          this.pool.writeFade(a.stream, a.offset, a.count, state.fade)
        }
      }

      // Кросс-фейд: уходящий тир гаснет к 0, затем освобождается. Пишем fade со
      // ЗНАКОМ МИНУС → шейдер берёт инвертированный дизер, покрытие комплементарно
      // входящему тиру (без «дыр» на середине перехода).
      if (state.outgoing) {
        const out = state.outgoing
        out.fade = Math.max(out.fade - step, 0.0)
        for (const a of out.allocations) {
          this.pool.writeFade(a.stream, a.offset, a.count, -out.fade)
        }
        if (out.fade <= 0.001) {
          for (const a of out.allocations) this.pool.release(a)
          this.used -= out.instanceCount
          state.outgoing = null
        }
      }

      if (state.pendingRemoval && state.fade <= 0.001) {
        for (const a of state.allocations) this.pool.release(a)
        this.used -= state.instanceCount
        if (state.outgoing) {
          for (const a of state.outgoing.allocations) this.pool.release(a)
          this.used -= state.outgoing.instanceCount
        }
        toRemove.push(key)
      }
    }

    for (const key of toRemove) {
      this.activeSectors.delete(key)
    }
  }

  /**
   * Принудительно деактивировать все секторы.
   */
  public deactivateAll(): void {
    for (const [, state] of this.activeSectors) {
      for (const a of state.allocations) this.pool.release(a)
      if (state.outgoing) {
        for (const a of state.outgoing.allocations) this.pool.release(a)
      }
    }
    this.activeSectors.clear()
    // Живых секторов не осталось — счётчик обнуляется, а не сводится вычитанием:
    // так расхождение, если оно где-то возникнет, не переживёт сброс
    this.used = 0
  }

  /**
   * Количество активных секторов.
   */
  public get activeCount(): number {
    return this.activeSectors.size
  }

  /**
   * Диагностическая информация.
   */
  public getDebugInfo(): {
    activeSectors: number
    byLod: { l0: number; near: number; l1: number }
    pendingRemoval: number
    usedInstances: number
    capacityFailures: number
  } {
    let l0 = 0,
      near = 0,
      l1 = 0,
      pending = 0
    for (const [, state] of this.activeSectors) {
      switch (state.lodLevel) {
        case LODLevel.Geometry:
          l0++
          break
        case LODLevel.GeometryNear:
          near++
          break
        case LODLevel.Billboard:
          l1++
          break
      }
      if (state.pendingRemoval) pending++
    }
    return {
      activeSectors: this.activeSectors.size,
      byLod: { l0, near, l1 },
      pendingRemoval: pending,
      usedInstances: this.used,
      capacityFailures: this.capacityFailures
    }
  }
}

export { SectorManager }
export type { LODThresholds, SectorState }

sources.tests/asteroidArchetypes/SectorAssignmen:
import { describe, expect, it, vi } from 'vitest'
import { BoxGeometry, Vector3 } from 'three'
import { AsteroidGenerator } from '@/core/renderables/DetailedRingStreamingSystem/AsteroidGenerator'
import { InstancePool, type Allocation } from '@/core/renderables/DetailedRingStreamingSystem/InstancePool'
import { SectorManager } from '@/core/renderables/DetailedRingStreamingSystem/SectorManager'
import { SectorGrid, sectorCenter, type SectorBounds } from '@/core/renderables/DetailedRingStreamingSystem/SectorGrid'
import { RadialDensityProfile } from '@/core/renderables/DetailedRingStreamingSystem/RadialDensityProfile'
import type { AsteroidProfileName } from '@/core/renderables/DetailedRingStreamingSystem/AsteroidProfiles'

const K = 14
const bounds: SectorBounds = { minRadius: 100, maxRadius: 200, minAngle: 0.1, maxAngle: 0.2, minY: 3, maxY: 9 }
const origin = new Vector3(12, 2, -7)
type Allocator = {
  allocateGeometryGroups(base: number, seed: number, count: number, bounds: SectorBounds): Allocation[] | null
}
const bits = (data: Float32Array) => new Uint32Array(data.buffer, data.byteOffset, data.length)

function scene(profile: AsteroidProfileName | undefined, relative = true) {
  const generator = new AsteroidGenerator({
    thickness: 8,
    minScale: 0.5,
    maxScale: 2,
    sizeExponent: 1.7,
    profile,
    relativeToSector: relative,
    volumetric: relative
  })
  generator.setDensityProfile(new RadialDensityProfile([0.1, 1, 0.4, 0.7], 100, 200))
  const geometry = new BoxGeometry()
  const pool = new InstancePool(
    { maxInstances: 1000 },
    { maxInstances: 1000 },
    { maxInstances: 10 },
    Array(K).fill(geometry),
    Array(K).fill(geometry),
    1
  )
  const grid = new SectorGrid({ innerRadius: 100, outerRadius: 200, cellSize: 5, ringId: 55, densityPerUnit: 1 })
  const manager = new SectorManager(
    grid,
    generator,
    pool,
    { l0MaxDistance: 4, l1MaxDistance: 9, nearEnterDistance: 1, nearExitDistance: 2 },
    relative ? origin : null
  )
  return { generator, pool, manager: manager as unknown as Allocator }
}

it.each([undefined, 'stony', 'carbonaceous', 'metallic', 'icy'] as const)(
  'prepared assignment preserves matrix bits and buffer ownership for %s',
  (profile) => {
    const { generator } = scene(profile)
    for (const count of [0, 1, 37]) {
      const assignment = generator.archetypeAssignment(-1, count, K)
      const saved = assignment.slice()
      const flat = generator.generateMatrices(-1, count, bounds)
      const first = generator.generateMatricesGrouped(-1, count, bounds, K, assignment)
      const second = generator.generateMatricesGrouped(-1, count, bounds, K, assignment)
      expect(first).toHaveLength(K)
      for (let k = 0; k < K; k++) {
        const indices = Array.from(assignment.keys()).filter((i) => assignment[i] === k)
        expect(first[k]).toHaveLength(indices.length * 16)
        expect(first[k].buffer).not.toBe(second[k].buffer)
        for (let j = 0; j < indices.length; j++) {
          expect(bits(first[k].subarray(j * 16, (j + 1) * 16))).toEqual(
            bits(flat.subarray(indices[j] * 16, (indices[j] + 1) * 16))
          )
        }
        const savedSecond = second[k].slice()
        first[k].fill(NaN)
        expect(bits(second[k])).toEqual(bits(savedSecond))
      }
      expect(assignment).toEqual(saved)
    }
  }
)

describe.each([0, K])('sector assignment reuse, stream base %i', (base) => {
  it.each([undefined, 'stony', 'carbonaceous', 'metallic', 'icy'] as const)(
    'preserves group order and pool attributes for %s',
    (profile) => {
      const { manager, generator, pool } = scene(profile, profile !== undefined)
      for (const count of [0, 1, 37]) {
        const seed = count === 1 ? -1 : 777
        const assignment = generator.archetypeAssignment(seed, count, K)
        const flat = generator.generateMatrices(seed, count, bounds)
        const allocations = manager.allocateGeometryGroups(base, seed, count, bounds)!
        expect(allocations).not.toBeNull()
        expect(allocations.reduce((sum, a) => sum + a.count, 0)).toBe(count)
        for (const allocation of allocations) {
          const k = allocation.stream - base
          const indices = Array.from(assignment.keys()).filter((i) => assignment[i] === k)
          expect(allocation.count).toBe(indices.length)
          const mesh = base ? pool.nearMeshes[k] : pool.geometryMeshes[k]
          const matrices = mesh.instanceMatrix.array as Float32Array
          for (let j = 0; j < indices.length; j++) {
            const slot = allocation.offset + j
            expect(bits(matrices.subarray(slot * 16, (slot + 1) * 16))).toEqual(
              bits(flat.subarray(indices[j] * 16, (indices[j] + 1) * 16))
            )
            expect(mesh.geometry.getAttribute('instanceFade').getX(slot)).toBe(0)
            expect(mesh.geometry.getAttribute('instanceMaxDistance').getX(slot)).toBe(9)
            const center = sectorCenter(bounds)
            const expected =
              profile === undefined
                ? [0, 0, 0]
                : [center.x - origin.x, center.y - origin.y, center.z - origin.z].map(Math.fround)
            const attr = mesh.geometry.getAttribute('instanceOrigin')
            expect([attr.getX(slot), attr.getY(slot), attr.getZ(slot)]).toEqual(expected)
          }
          pool.release(allocation)
        }
        expect(pool.getActiveCount().total).toBe(0)
      }
    }
  )

  it('computes the morphology assignment once per successful allocation', () => {
    const { manager, generator } = scene('stony')
    const selection = vi.spyOn(generator, 'archetypeAssignment')
    try {
      expect(manager.allocateGeometryGroups(base, 777, 200, bounds)).not.toBeNull()
      expect(selection).toHaveBeenCalledTimes(1)
    } finally {
      selection.mockRestore()
    }
  })

  it('rolls back partial allocation without matrix generation and can retry', () => {
    const { manager, generator, pool } = scene('stony')
    // Occupy the second nonempty group, forcing a failure after an earlier allocation.
    const assignment = generator.archetypeAssignment(777, 200, K)
    const occupiedGroups = [...new Set(assignment)].sort((a, b) => a - b)
    expect(occupiedGroups.length).toBeGreaterThan(1)
    const stream = base + occupiedGroups[1]
    const capacity = (base ? pool.nearMeshes : pool.geometryMeshes)[occupiedGroups[1]].instanceMatrix.count
    const blocker = pool.allocate(stream, capacity)!
    expect(blocker).not.toBeNull()
    const generation = vi.spyOn(generator, 'generateMatricesGrouped')
    try {
      expect(manager.allocateGeometryGroups(base, 777, 200, bounds)).toBeNull()
      expect(generation).not.toHaveBeenCalled()
      expect(pool.getActiveCount().total).toBe(capacity)
      pool.release(blocker)
      const retry = manager.allocateGeometryGroups(base, 777, 200, bounds)!
      expect(retry).not.toBeNull()
      expect(retry.reduce((sum, a) => sum + a.count, 0)).toBe(200)
      for (const a of retry) pool.release(a)
      expect(pool.getActiveCount().total).toBe(0)
    } finally {
      generation.mockRestore()
    }
  })
})

