import { BufferAttribute, Camera, Frustum, InstancedBufferAttribute, InstancedMesh, Matrix4 } from 'three'
import { IMPOSTOR_SLOT_CAPACITY } from './impostors/impostorLayout'

/** Stable CPU allocation slots, compacted into the mesh's existing GPU buffers. */
export class InstanceVisibility {
  public readonly matrix: InstancedBufferAttribute
  public readonly attributes = new Map<string, InstancedBufferAttribute>()
  private readonly slots: Uint32Array
  private readonly versions = new WeakMap<InstancedBufferAttribute, number>()
  private readonly projection = new Matrix4()
  private readonly frustum = new Frustum()
  private position?: ReturnType<InstancedMesh['geometry']['getAttribute']>
  private positionVersion = -1
  private radius = 0
  private visibleCount = -1

  public constructor(private readonly mesh: InstancedMesh) {
    // These clones stay on the CPU. The original render attributes retain their
    // identity, geometry-swap behavior and scene-owned GPU disposal lifecycle.
    this.matrix = new InstancedBufferAttribute(mesh.instanceMatrix.array.slice(), 16)
    for (const [name, attribute] of Object.entries(mesh.geometry.attributes)) {
      if (attribute instanceof InstancedBufferAttribute) {
        this.attributes.set(name, new InstancedBufferAttribute(attribute.array.slice(), attribute.itemSize, attribute.normalized, attribute.meshPerAttribute))
      }
    }
    this.slots = new Uint32Array(this.matrix.count)
  }

  public update(camera: Camera, count: number, shapeAmplitude: number): void {
    const mesh = this.mesh, position = mesh.geometry.getAttribute('position')
    const positionVersion = position instanceof BufferAttribute ? position.version : position.data.version
    if (position !== this.position || positionVersion !== this.positionVersion) {
      this.radius = 0
      for (let i = 0; i < position.count; i++) {
        this.radius = Math.max(this.radius, Math.hypot(position.getX(i), position.getY(i), position.getZ(i)))
      }
      this.position = position
      this.positionVersion = positionVersion
    }

    // Bound the radial residual in AsteroidShape.fbmGrad. Each simplex corner
    // is 42*(0.6-r*r)^4*dot(p,x), |p| <= 1.001. Four corners bound snoiseGrad
    // by 3.52; octave weights 0.5+0.25 bound fbm by 2.64. Use 4 for margin.
    // An origin-centered sphere also encloses off-center models at every spin.
    const radius = this.radius * (1 + 4 * Math.abs(shapeAmplitude))
    this.updateFrustum(camera)
    const matrices = this.matrix.array, origins = this.attributes.get('instanceOrigin')!.array
    let visibleCount = 0, changed = false
    for (let slot = 0; slot < count; slot++) {
      const m = slot * 16, o = slot * 3
      const a = matrices[m], b = matrices[m + 1], c = matrices[m + 2]
      const d = matrices[m + 4], e = matrices[m + 5], f = matrices[m + 6]
      const g = matrices[m + 8], h = matrices[m + 9], i = matrices[m + 10]
      // Match the shader's rejection of freed/degenerate slots.
      if (Math.abs(a * (e * i - f * h) - d * (b * i - c * h) + g * (b * f - c * e)) < 1e-20) continue
      const x = matrices[m + 12] + origins[o], y = matrices[m + 13] + origins[o + 1], z = matrices[m + 14] + origins[o + 2]
      const epsilon = 1e-5 * (1 + Math.abs(x) + Math.abs(y) + Math.abs(z))
      let visible = true
      for (const plane of this.frustum.planes) {
        const n = plane.normal
        const distance = n.x * x + n.y * y + n.z * z + plane.constant
        // A plane containing the center cannot exclude its sphere. Only outside
        // centers need the directional support norm; still check every plane.
        if (distance >= -epsilon) continue
        // Support of the transformed sphere along this plane normal. Unlike
        // max column length, this remains conservative under scale and shear.
        const extent = radius * Math.hypot(a * n.x + b * n.y + c * n.z, d * n.x + e * n.y + f * n.z, g * n.x + h * n.y + i * n.z)
        if (distance < -extent - epsilon) { visible = false; break }
      }
      if (!visible) continue
      if (this.slots[visibleCount] !== slot) changed = true
      this.slots[visibleCount++] = slot
    }
    this.commitVisible(visibleCount, changed)
  }

  public updateImpostors(camera: Camera, count: number, halfExtents: Float32Array, physicalSize: number): void {
    const details = this.attributes.get('instanceDetailEnd'), archetypes = this.attributes.get('instanceArchetype')
    if (!details || !archetypes || !halfExtents || halfExtents.length < IMPOSTOR_SLOT_CAPACITY || !Number.isFinite(physicalSize) || physicalSize <= 0) {
      this.restore(count)
      return
    }
    this.updateFrustum(camera)
    const matrices = this.matrix.array, origins = this.attributes.get('instanceOrigin')!.array
    let visibleCount = 0, changed = false
    for (let slot = 0; slot < count; slot++) {
      // The same draw can contain legacy billboards. Their footprint is not
      // described by the atlas, so retain their source slots unchanged.
      if (details.getX(slot) > 0) {
        const halfExtent = halfExtents[Math.trunc(Math.max(0, Math.min(IMPOSTOR_SLOT_CAPACITY - 1, archetypes.getX(slot))))]
        const m = slot * 16, o = slot * 3
        const a = matrices[m], b = matrices[m + 1], c = matrices[m + 2]
        const d = matrices[m + 4], e = matrices[m + 5], f = matrices[m + 6]
        const g = matrices[m + 8], h = matrices[m + 9], i = matrices[m + 10]
        // Match the atlas shader's rejection of invalid captures/degenerate slots.
        if (halfExtent <= 0 || Math.abs(a * (e * i - f * h) - d * (b * i - c * h) + g * (b * f - c * e)) < 1e-20) continue
        // The first capture-plane square reaches sqrt(2)*h, beyond the model
        // radius h. Use 2*h for margin. Frobenius bounds the maximum stretch
        // under scale/shear/reflection and is invariant under shader spin.
        // One sqrt per slot avoids four expensive directional support norms.
        const radius = 2 * halfExtent * physicalSize * Math.sqrt(a*a + b*b + c*c + d*d + e*e + f*f + g*g + h*h + i*i)
        const x = matrices[m + 12] + origins[o], y = matrices[m + 13] + origins[o + 1], z = matrices[m + 14] + origins[o + 2]
        const epsilon = 1e-5 * (1 + Math.abs(x) + Math.abs(y) + Math.abs(z))
        let visible = true
        // Three's first four planes are the sides. Preserve the shader's
        // reconstructed/logarithmic depth behavior at the near/far planes.
        for (let p = 0; p < 4; p++) {
          const plane = this.frustum.planes[p], n = plane.normal
          if (n.x * x + n.y * y + n.z * z + plane.constant < -radius - epsilon) { visible = false; break }
        }
        if (!visible) continue
      }
      if (this.slots[visibleCount] !== slot) changed = true
      this.slots[visibleCount++] = slot
    }
    this.commitVisible(visibleCount, changed)
  }

  /** Atlas loading, fallback and attribute removal must restore hidden slots. */
  public restore(count: number): void {
    let changed = false
    for (let slot = 0; slot < count; slot++) {
      if (this.slots[slot] !== slot) changed = true
      this.slots[slot] = slot
    }
    this.commitVisible(count, changed)
  }

  private updateFrustum(camera: Camera): void {
    this.mesh.updateWorldMatrix(true, false)
    this.projection.multiplyMatrices(camera.matrixWorldInverse, this.mesh.matrixWorld)
    this.projection.premultiply(camera.projectionMatrix)
    this.frustum.setFromProjectionMatrix(this.projection, camera.coordinateSystem)
  }

  private commitVisible(visibleCount: number, changed: boolean): void {
    const mesh = this.mesh
    changed ||= visibleCount !== this.visibleCount
    this.visibleCount = visibleCount
    mesh.count = visibleCount
    this.copyVisible(this.matrix, mesh.instanceMatrix, changed)
    for (const [name, source] of this.attributes) {
      const target = mesh.geometry.getAttribute(name)
      if (target instanceof InstancedBufferAttribute) this.copyVisible(source, target, changed)
    }
  }

  private copyVisible(source: InstancedBufferAttribute, target: InstancedBufferAttribute, changed: boolean): void {
    if (!changed && this.versions.get(source) === source.version) return
    this.versions.set(source, source.version)
    const size = source.itemSize, src = source.array, dst = target.array
    for (let start = 0; start < this.visibleCount;) {
      let end = start + 1
      while (end < this.visibleCount && this.slots[end] === this.slots[end - 1] + 1) end++
      const first = this.slots[start] * size, limit = first + (end - start) * size
      // A block copy pays off for longer spans; small spans avoid the temporary
      // subarray view. Count components so scalar attributes do not copy tiny blocks.
      if (limit - first >= 64) dst.set(src.subarray(first, limit), start * size)
      else for (let i = start * size, j = first; j < limit; i++, j++) dst[i] = src[j]
      start = end
    }
    // This prefix supersedes pending uploads, including when several view
    // updates occur before a render. Unused tail slots are outside mesh.count.
    target.clearUpdateRanges()
    if (this.visibleCount > 0) {
      target.addUpdateRange(0, this.visibleCount * size)
      target.needsUpdate = true
    }
  }
}

/**
 * RadialDensityProfile — радиальный профиль плотности камней из альфы текстуры кольца.
 *
 * Хранит кусочно-постоянную альфу по радиусу: бин i покрывает
 * [inner + i·step, inner + (i+1)·step), плюс префикс-интеграл
 * C(r) = ∫ α(t)·t dt — «массу» камней на единицу угла до радиуса r
 * (множитель t — потому что площадь дуги растёт с радиусом).
 *
 * Потребители (см. AsteroidRingSystem.__tryBuildDensityProfile):
 * - SectorGrid.weightForBand — средняя альфа полосы, взвешенная по площади →
 *   верное КОЛИЧЕСТВО камней сектора (пустоты дают 0 → сектор не генерится);
 * - AsteroidGenerator.sampleRadius — inverse-CDF семплинг радиуса с pdf ∝ α(r)·r →
 *   КОНЦЕНТРАЦИЯ камней в колечках.
 * Вместе поверхностная плотность камней = densityPerUnit · α(r).
 */
class RadialDensityProfile {
  /** Кусочно-постоянная альфа по радиальным бинам */
  private readonly alpha: Float32Array
  private readonly innerRadius: number
  private readonly outerRadius: number
  /** Радиальная ширина одного бина */
  private readonly step: number
  /**
   * cumulative[i] = ∫ α(r)·r dr от innerRadius до начала бина i (длина bins + 1).
   * Float64 — суммируем до тысячи слагаемых порядка r², точности float32 мало.
   */
  private readonly cumulative: Float64Array

  public constructor(alpha: ArrayLike<number>, innerRadius: number, outerRadius: number) {
    if (alpha.length < 1 || !(outerRadius > innerRadius)) {
      throw new Error('RadialDensityProfile: нужен непустой профиль и outerRadius > innerRadius')
    }

    this.alpha = Float32Array.from(alpha)
    this.innerRadius = innerRadius
    this.outerRadius = outerRadius
    this.step = (outerRadius - innerRadius) / this.alpha.length

    this.cumulative = new Float64Array(this.alpha.length + 1)
    for (let i = 0; i < this.alpha.length; i++) {
      const r0 = innerRadius + i * this.step
      const r1 = r0 + this.step
      this.cumulative[i + 1] = this.cumulative[i] + this.alpha[i] * 0.5 * (r1 * r1 - r0 * r0)
    }
  }

  /**
   * Средняя альфа полосы [minRadius, maxRadius], взвешенная по площади:
   * ∫ α(r)·r dr / ∫ r dr. 1 — полностью непрозрачная полоса, 0 — пустота.
   * Границы за пределами профиля клампятся.
   */
  public weightForBand(minRadius: number, maxRadius: number): number {
    const lo = this.clampRadius(minRadius)
    const hi = this.clampRadius(maxRadius)
    const areaTerm = 0.5 * (hi * hi - lo * lo)
    if (areaTerm <= 0) return 0

    return (this.massUpTo(hi) - this.massUpTo(lo)) / areaTerm
  }

  /**
   * Радиус по инверсии CDF с pdf ∝ α(r)·r внутри [minRadius, maxRadius] —
   * камни концентрируются в колечках с высокой альфой. Тратит ровно одно
   * случайное число u ∈ [0, 1) (детерминизм генератора не сдвигается).
   * Полоса без массы (сюда не должны попадать — weightForBand даёт 0) →
   * fallback: равномерно по площади, как без профиля.
   */
  public sampleRadius(minRadius: number, maxRadius: number, u: number): number {
    const massLo = this.massUpTo(minRadius)
    const total = this.massUpTo(maxRadius) - massLo

    if (total <= 0) {
      const r1Sq = minRadius * minRadius
      const r2Sq = maxRadius * maxRadius
      return Math.sqrt(r1Sq + u * (r2Sq - r1Sq))
    }

    const target = massLo + u * total

    // Наибольший бин с cumulative[i] <= target: плато нулевых бинов пропускается,
    // поиск попадает в бин с α > 0, содержащий target (бинарный поиск по префикс-массе).
    let lo = 0
    let hi = this.alpha.length - 1
    while (lo < hi) {
      const mid = (lo + hi + 1) >> 1
      if (this.cumulative[mid] <= target) {
        lo = mid
      } else {
        hi = mid - 1
      }
    }

    // Инверсия внутри бина: α·½(r² − r0²) = target − C(r0) → r.
    // α = 0 возможен лишь на краевом float (target == массе хвостового плато) —
    // тогда локальная масса 0 и берём начало бина.
    const binAlpha = this.alpha[lo]
    const binStart = this.innerRadius + lo * this.step
    const localMass = target - this.cumulative[lo]
    const r = binAlpha > 0 ? Math.sqrt(binStart * binStart + (2 * localMass) / binAlpha) : binStart

    // Страховка от краевых погрешностей float на границах полосы
    return Math.min(Math.max(r, minRadius), maxRadius)
  }

  /** ∫ α(r)·r dr от innerRadius до r (с клампом в диапазон профиля) */
  private massUpTo(r: number): number {
    const clamped = this.clampRadius(r)
    const bin = Math.min(Math.floor((clamped - this.innerRadius) / this.step), this.alpha.length - 1)
    const binStart = this.innerRadius + bin * this.step

    return this.cumulative[bin] + this.alpha[bin] * 0.5 * (clamped * clamped - binStart * binStart)
  }

  private clampRadius(r: number): number {
    return Math.min(Math.max(r, this.innerRadius), this.outerRadius)
  }
}

export { RadialDensityProfile }

const TWO_PI = Math.PI * 2

/**
 * AngularDensityProfile — азимутальный профиль плотности пояса (дуги, см.
 * buildBeltAngularProfile): кусочно-постоянный вес по углу, бин i покрывает
 * [2π·i/bins, 2π·(i+1)/bins) по atan2(z, x). Периодичен — интервалы и
 * префикс-масса продолжаются через 0/2π без шва.
 *
 * Радиальный аналог — RadialDensityProfile; здесь без множителя r: площадь
 * сектора уже учтена потребителем, вес — среднее профиля по углу.
 *
 * Потребители:
 * - SectorGrid.weightForRange — средний вес углового интервала сектора →
 *   КОЛИЧЕСТВО камней сектора;
 * - BeltPointLayer.sampleAngle — inverse-CDF розыгрыш угла точки.
 */
class AngularDensityProfile {
  private readonly weights: Float32Array
  /** Угловая ширина одного бина, радианы */
  private readonly step: number
  /** cumulative[i] = ∫ w dθ от 0 до начала бина i (длина bins + 1); Float64 — сумма тысячи слагаемых */
  private readonly cumulative: Float64Array
  /** Полная масса оборота, ∫₀^{2π} w dθ */
  private readonly total: number

  public constructor(weights: ArrayLike<number>) {
    if (weights.length < 1) throw new Error('AngularDensityProfile: нужен непустой профиль')

    this.weights = Float32Array.from(weights)
    this.step = TWO_PI / this.weights.length

    this.cumulative = new Float64Array(this.weights.length + 1)
    for (let i = 0; i < this.weights.length; i++) {
      this.cumulative[i + 1] = this.cumulative[i] + this.weights[i] * this.step
    }
    this.total = this.cumulative[this.weights.length]
  }

  /**
   * Средний вес интервала углов [a0, a1] (радианы, любой отсчёт: интервал
   * через 0/2π и отрицательные углы допустимы, a1 < a0 читается как дуга
   * вперёд от a0 по кругу). Интервал длиннее оборота даёт среднее по
   * обороту; вырожденный — вес в точке a0.
   */
  public weightForRange(a0: number, a1: number): number {
    let span = a1 - a0
    if (span >= TWO_PI) return this.total / TWO_PI
    if (span < 0) span = ((span % TWO_PI) + TWO_PI) % TWO_PI
    if (span <= 0) return this.weights[this.binOf(a0)]

    return (this.massUpTo(a0 + span) - this.massUpTo(a0)) / span
  }

  /**
   * Угол по инверсии CDF с pdf ∝ w(θ): тела концентрируются в дугах. Тратит
   * ровно одно случайное число u ∈ [0, 1); результат в [0, 2π). Профиль без
   * массы → равномерно, как без профиля.
   */
  public sampleAngle(u: number): number {
    if (this.total <= 0) return u * TWO_PI

    const target = u * this.total

    // Наибольший бин с cumulative[i] <= target (бинарный поиск по префикс-массе)
    let lo = 0
    let hi = this.weights.length - 1
    while (lo < hi) {
      const mid = (lo + hi + 1) >> 1
      if (this.cumulative[mid] <= target) {
        lo = mid
      } else {
        hi = mid - 1
      }
    }

    const w = this.weights[lo]
    const binStart = lo * this.step
    const theta = w > 0 ? binStart + (target - this.cumulative[lo]) / w : binStart

    // Краевой float у u → 1 упирается в 2π — тот же угол, что 0
    return theta >= TWO_PI ? 0 : Math.max(theta, 0)
  }

  /** ∫ w dθ от 0 до θ для любого вещественного θ — целые обороты по полной массе */
  private massUpTo(theta: number): number {
    const turns = Math.floor(theta / TWO_PI)
    const local = theta - turns * TWO_PI
    const bin = Math.min(Math.floor(local / this.step), this.weights.length - 1)

    return turns * this.total + this.cumulative[bin] + this.weights[bin] * (local - bin * this.step)
  }

  private binOf(theta: number): number {
    const local = theta - Math.floor(theta / TWO_PI) * TWO_PI
    return Math.min(Math.floor(local / this.step), this.weights.length - 1)
  }
}

export { AngularDensityProfile }

/**
 * Доля массы треугольного распределения (пик в нуле, нули на ±half) в полосе
 * [y0, y1]. Тем же законом генератор раскладывает камни по толщине кольца
 * (см. triangularHeight) — здесь он применён к целой ячейке.
 */
export function triangularMass(y0: number, y1: number, half: number): number {
  if (half <= 0) return 0

  return triangularCdf(y1, half) - triangularCdf(y0, half)
}

/** Функция распределения: 0 на −half, 0.5 в нуле, 1 на +half */
function triangularCdf(y: number, half: number): number {
  const t = Math.max(-half, Math.min(half, y)) / half

  return t >= 0 ? 0.5 + t - (t * t) * 0.5 : 0.5 + t + (t * t) * 0.5
}

import { BufferGeometry } from 'three'
import { ASTEROID_PROFILES, type AsteroidProfileName } from '../AsteroidProfiles'
import { SeededRandom, hashSectorKey } from '../SeededRandom'
import { ArchetypeShape, generateArchetypeParams, type ArchetypeMorphology } from './ArchetypeShape'
import { buildArchetypeGeometry } from './ArchetypeGeometry'

/**
 * Порядок процедурных категорий в библиотеке: индексы каждой морфологии
 * контигуальны и идут в этом порядке. fragment первым — k=0 всегда осколок
 * (преемственность кэша). Реальные модели занимают ХВОСТ библиотеки после них
 * (категория 'real', см. archetypeLayout).
 */
const MORPHOLOGY_ORDER: readonly ArchetypeMorphology[] = ['fragment', 'rubble', 'binary', 'top', 'cratered']

/** Категория слота библиотеки: процедурная морфология либо реальная модель формы */
type LibraryCategory = ArchetypeMorphology | 'real'

/** Настройка реальной части библиотеки (по умолчанию — из профиля) */
interface RealModelsOverride {
  shapeModels: readonly string[]
  realShare: number
}

/** Раскладка библиотеки: сколько слотов процедурных и какие реальные модели в хвосте */
interface ArchetypeLayout {
  proceduralCount: number
  /** Имена моделей по слотам хвоста (список профиля по кругу) */
  realModels: string[]
}

/**
 * Раскладка библиотеки из `count` слотов: хвост под реальные модели —
 * round(count · realShare), но не больше count − 1 (k=0 всегда процедурный
 * осколок) и только при непустом списке; список профиля идёт по кругу, если
 * слотов больше моделей.
 */
function archetypeLayout(profile: AsteroidProfileName, count: number, override?: RealModelsOverride): ArchetypeLayout {
  const source = override ?? ASTEROID_PROFILES[profile]
  const names = source.shapeModels
  const share = source.realShare
  if (names.length === 0 || share <= 0 || count <= 1) return { proceduralCount: count, realModels: [] }

  const realCount = Math.min(count - 1, Math.max(0, Math.round(count * share)))
  const realModels: string[] = []
  for (let i = 0; i < realCount; i++) realModels.push(names[i % names.length])
  return { proceduralCount: count - realCount, realModels }
}

/**
 * Число архетипов каждой морфологии в библиотеке из `count` штук: пороговое
 * разбиение по кумулятивным весам профиля в порядке MORPHOLOGY_ORDER
 * (end_j = round(count · Σ_{i≤j} w_i), count_j = end_j − end_{j−1}). Когда
 * count не меньше числа категорий с ненулевым весом, округление не имеет права
 * выродить такую категорию в 0 — у неё отбирается один индекс у категории с
 * наибольшим текущим избытком (детерминированно: перебор в порядке
 * MORPHOLOGY_ORDER, наибольший донор побеждает).
 */
function morphologyCounts(profile: AsteroidProfileName, count: number): Record<ArchetypeMorphology, number> {
  const w = ASTEROID_PROFILES[profile].morphologyWeights
  const weights = MORPHOLOGY_ORDER.map((m) => w[m])

  const counts: number[] = []
  let cumulative = 0
  let prevEnd = 0
  for (let j = 0; j < weights.length; j++) {
    cumulative += weights[j]
    const end = j === weights.length - 1 ? count : Math.round(count * cumulative)
    counts.push(end - prevEnd)
    prevEnd = end
  }

  const mins: number[] = weights.map((v) => (v > 0 ? 1 : 0))
  const nonZero = mins.reduce((s: number, v: number) => s + v, 0)
  if (count >= nonZero) {
    for (let i = 0; i < counts.length; i++) {
      while (counts[i] < mins[i]) {
        let donor = -1
        for (let j = 0; j < counts.length; j++) {
          if (j === i) continue
          if (counts[j] > mins[j] && (donor === -1 || counts[j] > counts[donor])) donor = j
        }
        if (donor === -1) break
        counts[donor]--
        counts[i]++
      }
    }
  }

  // Преемственность кэша: k=0 всегда осколок. Округление может отдать
  // единственный индекс другой категории (carbonaceous, count=1: round(0.4)=0) —
  // тогда индекс забирается у самой крупной категории
  if (count > 0 && counts[0] === 0) {
    let donor = 1
    for (let j = 2; j < counts.length; j++) if (counts[j] > counts[donor]) donor = j
    counts[donor]--
    counts[0]++
  }

  const result = {} as Record<ArchetypeMorphology, number>
  MORPHOLOGY_ORDER.forEach((m, i) => (result[m] = counts[i]))
  return result
}

/** Диапазон индексов библиотеки одной категории (start, count); count может быть 0 */
interface MorphologyRange {
  morphology: LibraryCategory
  start: number
  count: number
}

/**
 * Диапазоны индексов библиотеки: процедурные категории в порядке
 * MORPHOLOGY_ORDER по голове (размером proceduralCount), затем хвост 'real' —
 * для раскладки инстансов по размеру (см. AsteroidGenerator.pickArchetype).
 */
function morphologyRanges(profile: AsteroidProfileName, count: number, override?: RealModelsOverride): MorphologyRange[] {
  const layout = archetypeLayout(profile, count, override)
  const counts = morphologyCounts(profile, layout.proceduralCount)
  const ranges: MorphologyRange[] = []
  let start = 0
  for (const morphology of MORPHOLOGY_ORDER) {
    ranges.push({ morphology, start, count: counts[morphology] })
    start += counts[morphology]
  }
  ranges.push({ morphology: 'real', start, count: layout.realModels.length })
  return ranges
}

/**
 * Категория k-го слота библиотеки из `count` штук профиля `profile` (чистая
 * функция — тестируется отдельно от кэша геометрий). Преемственность: k=0
 * всегда 'fragment'; хвост — 'real'.
 */
function morphologyForIndex(profile: AsteroidProfileName, k: number, count: number, override?: RealModelsOverride): LibraryCategory {
  for (const range of morphologyRanges(profile, count, override)) {
    if (k < range.start + range.count) return range.morphology
  }
  return 'real'
}

/**
 * Библиотека запечённых архетипов: K форм на профиль. Кэш модульный —
 * кольца одного профиля/конфигурации делят геометрии (single source
 * VBO, память не растёт с числом колец). Сид k-го архетипа независим от
 * count → усечение/расширение библиотеки не «пере жёвывает» формы (но
 * морфология k-го архетипа зависит от count — см. morphologyForIndex).
 */
const cache = new Map<string, BufferGeometry[]>()

function getArchetypeGeometries(
  profile: AsteroidProfileName,
  count: number,
  detail: number,
  radius: number
): BufferGeometry[] {
  const key = `${profile}|${count}|${detail}|${radius}`
  const cached = cache.get(key)
  if (cached) return cached

  const profileIndex = Object.keys(ASTEROID_PROFILES).indexOf(profile)
  const geometries: BufferGeometry[] = []
  for (let k = 0; k < count; k++) {
    // Сид согласован с 2a: k=0 воспроизводит прежний единственный архетип.
    // Слот реальной модели получает процедурную ЗАГЛУШКУ-осколок: пул строится
    // сразу, а геометрия стрима подменяется по приходу бинарника
    // (AsteroidRingSystem → InstancePool.replaceArchetypeGeometry)
    const category = morphologyForIndex(profile, k, count)
    const morphology: ArchetypeMorphology = category === 'real' ? 'fragment' : category
    const rng = new SeededRandom(hashSectorKey(0xa57, k, profileIndex))
    const shape = new ArchetypeShape(generateArchetypeParams(rng, morphology))
    geometries.push(buildArchetypeGeometry(shape, detail, radius))
  }
  cache.set(key, geometries)
  return geometries
}

export { getArchetypeGeometries, morphologyForIndex, morphologyRanges, archetypeLayout, MORPHOLOGY_ORDER }
export type { MorphologyRange, LibraryCategory, ArchetypeLayout, RealModelsOverride }

