import { BoxGeometry, PerspectiveCamera, Vector3 } from 'three'
import { AsteroidGenerator as BaselineGenerator } from './reuse-archetype-baseline-AsteroidGenerator-2026-10-27'
import { SectorManager as BaselineManager } from './reuse-archetype-baseline-SectorManager-2026-10-27'
import { AsteroidGenerator as CurrentGenerator } from '/src/core/renderables/DetailedRingStreamingSystem/AsteroidGenerator'
import { SectorManager as CurrentManager } from '/src/core/renderables/DetailedRingStreamingSystem/SectorManager'
import { SectorGrid } from '/src/core/renderables/DetailedRingStreamingSystem/SectorGrid'
import { InstancePool } from '/src/core/renderables/DetailedRingStreamingSystem/InstancePool'
import { RadialDensityProfile } from '/src/core/renderables/DetailedRingStreamingSystem/RadialDensityProfile'
import { getInitializedSimulationRuntime } from '/src/ui/runtime/simulationRuntime'
import { Tokens } from '/src/core/providers/tokens'
import { diagnoseMotionCpu } from './motion-cpu-2026-10-26.browser'
import { state } from './profile.browser'

const stats = (values: number[]) => {
  const sorted = values.slice().sort((a, b) => a - b)
  return { count: values.length, p50: sorted[15], p95: sorted[30], max: sorted[31] }
}
const hash = async (data: Uint8Array) => Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', data)), b => b.toString(16).padStart(2, '0')).join('')
function output(pool: InstancePool, allocations: any[]) {
  return allocations.map(a => {
    return { stream: a.stream, count: a.count, arrays: [
      ((pool as any).matrixAttribute(a.stream).array as Float32Array).slice(a.offset * 16, (a.offset + a.count) * 16),
      ...['instanceFade', 'instanceOrigin', 'instanceMaxDistance'].map(name => {
        const attr = (pool as any).instanceAttribute(a.stream, name)
        return (attr.array as Float32Array).slice(a.offset * attr.itemSize, (a.offset + a.count) * attr.itemSize)
      })
    ] }
  })
}
function equal(a: ReturnType<typeof output>, b: ReturnType<typeof output>) {
  if (a.length !== b.length) throw Error('Group count changed')
  for (let k = 0; k < a.length; k++) {
    if (a[k].stream !== b[k].stream || a[k].count !== b[k].count) throw Error('Group allocation changed')
    for (let attr = 0; attr < a[k].arrays.length; attr++) {
      const x = new Uint32Array(a[k].arrays[attr].buffer), y = new Uint32Array(b[k].arrays[attr].buffer)
      if (x.length !== y.length) throw Error('Attribute length changed')
      for (let i = 0; i < x.length; i++) if (x[i] !== y[i]) throw Error(`Output changed at group ${k} attribute ${attr} word ${i}`)
    }
  }
}

export async function benchmark() {
  const engine: any = getInitializedSimulationRuntime()!.container.get(Tokens.Engine)
  const proto: any = CurrentManager.prototype
  const oldFrame = engine.renderFrame, oldAllocate = proto.allocateGeometryGroups, oldAssignment = CurrentGenerator.prototype.archetypeAssignment
  const owners = new Map<any, number>(), inputs: any[] = [], calls: any[] = [], live: ReturnType<typeof output>[] = []
  let frame = -1, nextFrame = 0, assignments = 0, failed = 0
  engine.renderFrame = function () {
    if (nextFrame >= 96) return oldFrame.call(this)
    frame = nextFrame++
    try { return oldFrame.call(this) } finally { frame = -1 }
  }
  CurrentGenerator.prototype.archetypeAssignment = function (...args) { assignments++; return oldAssignment.apply(this, args) }
  proto.allocateGeometryGroups = function (base: number, seed: number, count: number, bounds: any) {
    const beforeAssignments = assignments
    const result = oldAllocate.call(this, base, seed, count, bounds)
    if (frame >= 0) {
      if (!result) { failed++; return result }
      let owner = owners.get(this)
      if (owner === undefined) {
        owner = inputs.length; owners.set(this, owner)
        const density = this.generator.densityProfile
        inputs.push({ config: { ...this.generator.config }, k: this.pool.geometryStreamCount, thresholds: { ...this.thresholds }, density: density ? {
          alpha: Array.from(density.alpha), inner: density.innerRadius, outer: density.outerRadius
        } : null })
      }
      calls.push({ frame, owner, base, seed, count, bounds: { ...bounds }, origin: this.origin?.toArray() ?? null, assignments: assignments - beforeAssignments })
      live.push(output(this.pool, result))
    }
    return result
  }
  const replayPools: InstancePool[] = [], geometries: BoxGeometry[] = []
  try {
    const motion = await diagnoseMotionCpu('passes', true)
    engine.stop(); engine.renderFrame = oldFrame; proto.allocateGeometryGroups = oldAllocate; CurrentGenerator.prototype.archetypeAssignment = oldAssignment
    if (nextFrame !== 96 || calls.length < 32 || !inputs.length) throw Error('Incomplete allocation capture')
    const snapshot = state(), before = JSON.stringify({ inputs, calls })
    const create = (Generator: any, Manager: any) => inputs.map((input, owner) => {
      const generator = new Generator({ ...input.config })
      if (input.density) generator.setDensityProfile(new RadialDensityProfile(input.density.alpha, input.density.inner, input.density.outer))
      const capacity = Math.max(...calls.filter(c => c.owner === owner).map(c => c.count), 1) * input.k
      const geometry = new BoxGeometry(); geometries.push(geometry)
      const pool = new InstancePool({ maxInstances: capacity }, { maxInstances: capacity }, { maxInstances: 1 }, Array(input.k).fill(geometry), Array(input.k).fill(geometry), 1)
      // Empty streams skip visibility initialization. Seed one slot per stream
      // before updating, then release it; replay now writes the production CPU buffers.
      const initial = Array.from({ length: input.k * 2 }, (_, stream) => pool.allocate(stream, 1)!)
      pool.updateVisibility(new PerspectiveCamera())
      for (const allocation of initial) pool.release(allocation)
      pool.commitUpdates()
      if ((pool as any).streams.slice(0, input.k * 2).some((stream: any) => !stream.visibility)) throw Error('Replay visibility missing')
      replayPools.push(pool)
      const grid = new SectorGrid({ innerRadius: 100, outerRadius: 200, cellSize: 5, ringId: 55, densityPerUnit: 1 })
      return new Manager(grid, generator, pool, { ...input.thresholds }, null)
    })
    const baseline = create(BaselineGenerator, BaselineManager), current = create(CurrentGenerator, CurrentManager)
    const run = (managers: any[], verify = false) => {
      let checksum = 0
      for (let i = 0; i < calls.length; i++) {
        const call = calls[i], manager = managers[call.owner], pool = manager.pool
        manager.origin = call.origin ? new Vector3(...call.origin) : null
        const allocations = manager.allocateGeometryGroups(call.base, call.seed, call.count, call.bounds)
        if (!allocations) throw Error('Replay allocation failed')
        if (verify) equal(output(pool, allocations), live[i])
        for (const a of allocations) { checksum += a.count + a.stream; pool.release(a) }
        pool.commitUpdates()
      }
      return checksum
    }
    run(baseline, true); run(current, true)
    const samples = { baseline: [] as number[], current: [] as number[] }, checksums: number[] = []
    const measure = (name: 'baseline' | 'current') => {
      const started = performance.now(), checksum = run(name === 'baseline' ? baseline : current)
      const elapsed = performance.now() - started
      checksums.push(checksum); return elapsed
    }
    for (let i = 0; i < 6; i++) { measure('baseline'); measure('current'); await new Promise(r => setTimeout(r, 0)) }
    for (let i = 0; i < 32; i++) {
      for (const name of (i % 2 ? ['current', 'baseline'] : ['baseline', 'current']) as ('baseline' | 'current')[]) samples[name].push(measure(name))
      await new Promise(r => setTimeout(r, 0))
    }
    run(baseline, true); run(current, true)
    if (checksums.some(v => v !== checksums[0]) || before !== JSON.stringify({ inputs, calls })) throw Error('Inputs or results drifted')
    const arrays = live.flatMap(groups => groups.flatMap(g => g.arrays))
    const bytes = arrays.reduce((sum, data) => sum + data.byteLength, 0), all = new Uint8Array(bytes)
    let offset = 0
    for (const data of arrays) { all.set(new Uint8Array(data.buffer, data.byteOffset, data.byteLength), offset); offset += data.byteLength }
    const summary = { baseline: stats(samples.baseline), current: stats(samples.current) }
    const improvement = 1 - summary.current.p50 / summary.baseline.p50
