      capture: { frames: 96, calls: calls.length, failed, instances: calls.reduce((sum, call) => sum + call.count, 0), assignmentCalls: calls.reduce((sum, call) => sum + call.assignments, 0), motionSummary: motion.summary.cpu['whole-frame'] },
