import { createServer } from 'vite'
import { chromium } from '@playwright/test'
import { readFile, writeFile } from 'node:fs/promises'
import { createHash } from 'node:crypto'
Object.assign(process.env, { VITE_FS_DRIVER: 's3', VITE_S3_URL: 'https://storage.yandexcloud.net', VITE_FILE_BUCKET: 'textures', VITE_SHOW_STATS_PANEL: 'false', VITE_SKY_SOURCE: 'gaia' })
const red = process.argv.includes('--red'), phase = red ? 'red' : 'green'
const output = `benchmark-results/heavy-scenes/reuse-archetype-${phase}-2026-10-27.json`
const sha = text => createHash('sha256').update(text).digest('hex')
const sourceHashes = { original: {}, current: {} }
for (const name of ['AsteroidGenerator', 'SectorManager']) {
  const original = await readFile(`benchmark-results/heavy-scenes/reuse-archetype-baseline-${name}-2026-10-27.source.txt`, 'utf8')
  const current = await readFile(`src/core/renderables/DetailedRingStreamingSystem/${name}.ts`, 'utf8')
  if (red && current.replaceAll('\r\n', '\n') !== original.replaceAll('\r\n', '\n')) throw Error('RED requires unmodified baseline production in an isolated copy')
  sourceHashes.original[name] = sha(original); sourceHashes.current[name] = sha(current)
}
const report = { baselineCommit: '39a06bc08734616c91cc49411f6e2272690e96b0', phase, sourceHashes, startedAt: new Date().toISOString(), rows: [], errors: [], warnings: [], assetFailures: [], abortedRequests: [], outcome: 'failed' }
await writeFile(output, JSON.stringify(report, null, 2), { flag: 'wx' })
let server, browser
try {
  server = await createServer({ server: { host: '127.0.0.1', port: 8094, strictPort: true, hmr: false } }); await server.listen()
  browser = await chromium.launch({ channel: 'chrome', headless: true })
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 })
  page.on('pageerror', e => report.errors.push(e.stack || e.message))
  page.on('console', m => { if (m.type() === 'error') report.errors.push(m.text()); if (m.type() === 'warning') report.warnings.push(m.text()) })
  page.on('response', r => { if (r.status() >= 400) report.assetFailures.push(`${r.status()} ${r.url()}`) })
  page.on('requestfailed', r => (r.failure()?.errorText?.includes('ERR_ABORTED') ? report.abortedRequests : report.assetFailures).push(`${r.failure()?.errorText} ${r.url()}`))
  await page.goto('http://127.0.0.1:8094/'); await page.getByRole('button', { name: /^Run / }).first().waitFor()
  for (const [id, actor] of [[13, 135], [12, 127]]) {
    console.log('Starting', id, phase)
    await page.evaluate(async id => Promise.race([(await import('/tests/browser/scenarioSoak.browser.ts')).selectScenario(id), new Promise((_, reject) => setTimeout(() => reject(Error('Startup timeout')), 180000))]), id)
    const view = await page.evaluate(async id => (await import('/benchmark-results/heavy-scenes/profile.browser.ts')).setView(id, 'belt'), actor)
    await page.waitForTimeout(5000)
    const row = await page.evaluate(async () => (await import('/benchmark-results/heavy-scenes/reuse-archetype-2026-10-27.browser.ts')).benchmark())
    if (/SwiftShader|software|llvmpipe/i.test(row.snapshot.renderer)) throw Error('Software renderer')
    report.rows.push({ id, view, ...row }); await writeFile(output, JSON.stringify(report, null, 2))
    console.log('ALLOCATION', id, JSON.stringify({ summary: row.summary, improvement: row.improvement, capture: row.capture, parity: row.parity, gate: row.gate }))
    await page.evaluate(async () => (await import('/tests/browser/scenarioSoak.browser.ts')).returnToMenu())
    if (report.errors.length || report.warnings.length || report.assetFailures.length || report.abortedRequests.length) throw Error('Browser/shader/asset issue')
  }
  report.outcome = report.rows.every(row => row.gate) ? 'completed' : 'performance-gate-failed'
  if (report.outcome !== 'completed') { console.error('Allocation batch speedup is below 10%'); process.exitCode = 1 }
} catch (e) { report.failure = e.stack || e.message; console.error(e); process.exitCode = 1 }
finally { report.finishedAt = new Date().toISOString(); await writeFile(output, JSON.stringify(report, null, 2)); await browser?.close(); await server?.close() }

