    'prepare-reuse-archetype-2026-10-27.mjs', 'reuse-archetype-2026-10-27.browser.ts', 'run-reuse-archetype-2026-10-27.mjs',
    'reuse-archetype-capture-first-2026-10-27.browser.txt', 'reuse-archetype-cold-pools-2026-10-27.browser.txt',
    'run-reuse-archetype-verification-2026-10-27.ps1', 'archive-reuse-archetype-2026-10-27.mjs',
    ...['AsteroidGenerator', 'SectorManager'].flatMap(name => [`reuse-archetype-baseline-${name}-2026-10-27.source.txt`, `reuse-archetype-baseline-${name}-2026-10-27.ts`])
  ].map(name => root + name)
]
const evidenceFiles = ['package-lock.json', ...[
  'reuse-archetype-red-capture-first-2026-10-27.json', 'reuse-archetype-red-capture-first-2026-10-27.log',
  'reuse-archetype-red-cold-pools-2026-10-27.json', 'reuse-archetype-red-cold-pools-2026-10-27.log',
  'reuse-archetype-red-unit-2026-10-27.log', 'reuse-archetype-red-unit-complete-2026-10-27.log',
  'reuse-archetype-focused-unit-2026-10-27.log',
  'reuse-archetype-red-2026-10-27.json', 'reuse-archetype-red-2026-10-27.log',
  'reuse-archetype-green-2026-10-27.json', 'reuse-archetype-green-2026-10-27.log',
  'reuse-archetype-verification-2026-10-27.json', 'reuse-archetype-full-test-2026-10-27.log',
  'reuse-archetype-lint-2026-10-27.log', 'reuse-archetype-build-2026-10-27.log',
  'reuse-archetype-full-browser-2026-10-27.log', 'reuse-archetype-full-browser-2026-10-27.json'
].map(name => root + name)]
const stats = values => {
  const sorted = values.slice().sort((a, b) => a - b)
  assert.equal(sorted.length, 32)
  return { count: 32, p50: sorted[15], p95: sorted[30], max: sorted[31] }
}
const checkClean = report => {
  for (const key of ['errors', 'warnings', 'assetFailures', 'abortedRequests']) assert.equal(report[key].length, 0, key)
  assert.equal(report.rows.length, 2)
}

function verify(archive) {
  assert.equal(archive.base, base)
  for (const name of ['AsteroidGenerator', 'SectorManager']) {
    const path = `src/core/renderables/DetailedRingStreamingSystem/${name}.ts`
    const original = read(`${root}reuse-archetype-baseline-${name}-2026-10-27.source.txt`)
    assert.equal(normalize(original), normalize(execFileSync('git', ['show', `${base}:${path}`], { encoding: 'utf8' })))
    let adapted = original.replaceAll("from './", "from '/src/core/renderables/DetailedRingStreamingSystem/")
    adapted = adapted.replace("from '/src/core/renderables/DetailedRingStreamingSystem/AsteroidGenerator'", "from './reuse-archetype-baseline-AsteroidGenerator-2026-10-27'")
    assert.equal(read(`${root}reuse-archetype-baseline-${name}-2026-10-27.ts`), adapted)
    for (const phase of ['red', 'green']) {
      const hashes = archive.performance[phase].sourceHashes
      assert.equal(hashes.original[name], digest(Buffer.from(original)))
      assert.equal(hashes.current[name], digest(Buffer.from(phase === 'red' ? original : read(path))))
    }
  }
  for (const entry of archive.provenance) {
    const bytes = readFileSync(entry.path)
    assert.equal(digest(bytes), entry.sha256, entry.path); assert.equal(bytes.length, entry.bytes, entry.path)
  }
  for (const [path, text] of Object.entries(archive.sources)) assert.equal(read(path), text, path)
  for (const path of sources.filter(path => path.startsWith('src/') && !production.includes(path))) {
    assert.equal(normalize(read(path)), normalize(execFileSync('git', ['show', `${base}:${path}`], { encoding: 'utf8' })), path)
  }
  for (const phase of ['red', 'green']) {
    const report = archive.performance[phase]
    assert.deepEqual(report, json(`${root}reuse-archetype-${phase}-2026-10-27.json`))
    checkClean(report)
    assert.equal(report.baselineCommit, base)
    assert.deepEqual(report.rows.map(row => row.id), [13, 12])
    assert.equal(report.outcome, phase === 'red' ? 'performance-gate-failed' : 'completed')
    for (const row of report.rows) {
      assert.deepEqual(row.summary.baseline, stats(row.samples.baseline))
      assert.deepEqual(row.summary.current, stats(row.samples.current))
      assert.equal(row.improvement, 1 - row.summary.current.p50 / row.summary.baseline.p50)
      assert.equal(row.gate, row.improvement >= 0.1); assert.equal(row.gate, phase === 'green')
      assert.equal(row.capture.frames, 96); assert.equal(row.capture.calls, row.calls.length)
      assert.equal(row.capture.failed, 0)
      assert.equal(row.capture.instances, row.calls.reduce((sum, call) => sum + call.count, 0))
      assert.equal(row.capture.assignmentCalls, row.calls.length * (phase === 'red' ? 2 : 1))
      assert(row.calls.every(call => call.assignments === (phase === 'red' ? 2 : 1)))
      assert(row.calls.every(call => call.frame >= 0 && call.frame < 96 && call.owner < row.inputs.length))
      assert.equal(row.parity.bytesPerComparison, row.capture.instances * 84)
      assert.equal(row.parity.comparisons, 4); assert.equal(row.parity.identicalToLive, true); assert.equal(row.parity.beforeAndAfter, true)
      assert.equal(row.parity.inputsSha256, digest(Buffer.from(JSON.stringify({ inputs: row.inputs, calls: row.calls }))))
      assert.match(row.parity.liveSha256, /^[a-f0-9]{64}$/)
    }
  }
  for (const row of archive.performance.green.rows) {
    const previous = archive.performance.red.rows.find(candidate => candidate.id === row.id)
    assert.deepEqual(row.inputs, previous.inputs)
    const workload = calls => calls.map(({ assignments, ...call }) => call)
    assert.deepEqual(workload(row.calls), workload(previous.calls))
    assert.equal(row.parity.liveSha256, previous.parity.liveSha256)
  }
  const checks = json(root + 'reuse-archetype-verification-2026-10-27.json')
  assert.deepEqual(archive.verification.steps, checks)
  assert.deepEqual(checks.map(step => step.name), ['full-test', 'lint', 'build', 'full-browser'])
  assert(checks.every(step => step.exitCode === 0 && step.seconds > 0))
  const red = cleanLog(root + 'reuse-archetype-red-unit-complete-2026-10-27.log')
  assert.match(red, /2 failed \| 17 passed \(19\)/); assert.match(red, /but got 2 times/)
  const focused = cleanLog(root + 'reuse-archetype-focused-unit-2026-10-27.log')
  assert.match(focused, /700 passed \| 1 skipped/)
  const full = cleanLog(root + 'reuse-archetype-full-test-2026-10-27.log')
  assert.match(full, /5619 passed \| 7 skipped/)
  const browser = json(root + 'reuse-archetype-full-browser-2026-10-27.json')
  assert.deepEqual(archive.verification.browserStats, browser.stats)
  assert.equal(browser.stats.expected, 48); assert.equal(browser.stats.unexpected, 0); assert.equal(browser.stats.skipped, 0); assert.equal(browser.stats.flaky, 0)
  assert.match(cleanLog(root + 'reuse-archetype-build-2026-10-27.log'), /built in/)
  const cold = json(root + 'reuse-archetype-red-cold-pools-2026-10-27.json')
  assert.deepEqual(archive.diagnostics.coldPools, cold); checkClean(cold)
  assert.equal(cold.outcome, 'performance-gate-failed')
  const failed = json(root + 'reuse-archetype-red-capture-first-2026-10-27.json')
  assert.deepEqual(archive.diagnostics.firstCapture, failed)
  assert.match(failed.failure, /Output changed at group 0 attribute 0 word 0/)
  if (archive.review) {
    assert.deepEqual(archive.review, json(root + 'reuse-archetype-review-2026-10-27.json'))
    assert.equal(archive.review.critical, 0); assert.equal(archive.review.important, 0); assert.equal(archive.review.minor, 0)
  }
  console.log(JSON.stringify({ verified: true, hashes: archive.provenance.length, unitTests: 5619, browserTests: 48, rows: archive.performance.green.rows.map(row => ({ id: row.id, p50: row.summary, improvement: row.improvement, bytes: row.parity.bytesPerComparison })) }))
}

if (process.argv.includes('--verify')) {
  verify(json(output))
} else {
  const reviewPath = root + 'reuse-archetype-review-2026-10-27.json'
  const all = [...sources, ...evidenceFiles, ...(existsSync(reviewPath) ? [reviewPath] : [])]
  const archive = {
    base, createdAt: new Date().toISOString(), title: 'Reuse geometry sector archetype assignment',
    production, sources: Object.fromEntries(sources.map(path => [path, read(path)])),
    performance: Object.fromEntries(['red', 'green'].map(phase => [phase, json(`${root}reuse-archetype-${phase}-2026-10-27.json`)])),
    diagnostics: {
      firstCapture: json(root + 'reuse-archetype-red-capture-first-2026-10-27.json'),
      coldPools: json(root + 'reuse-archetype-red-cold-pools-2026-10-27.json'),
      explanation: 'First capture incorrectly read compact render attributes before visibility update; corrected to CPU source accessors. Cold-pool original/original control preserved separately. Final paired runs initialize and assert visibility on each replay geometry stream. No production edits during either diagnostic; no timings compared across harness versions.'
    },
    verification: { steps: json(root + 'reuse-archetype-verification-2026-10-27.json'), browserStats: json(root + 'reuse-archetype-full-browser-2026-10-27.json').stats, focused: { passed: 700, skipped: 1 }, unit: { passed: 5619, skipped: 7 }, newFixtures: 19 },
    reproduction: 'Use embedded sources and retained exact inputs with original Git/current constructors. Runner refuses to overwrite report paths. RED requires baseline production in an isolated copy and empty outputs; --red verifies both production files before starting. Provision existing dependencies, Chrome and cloud assets. Historical output buffers are hashes only; reproduce to compare all live bits again. Read-only --verify needs retained ignored evidence files and matching source tree; later production edits invalidate current-tree provenance by design.',
    scope: 'Paired CPU allocation/write/release/commit batch with independent real pools, initialized visibility and ample capacity, frozen successful motion inputs, substitute box geometry. It does not measure full frames, FPS, GPU rendering, other devices, or real pool fragmentation. Failure rollback checked in unit tests. Complete matrix/fade/origin/distance buffers compared in memory four times per scene; raw output buffers not retained.',
    review: existsSync(reviewPath) ? json(reviewPath) : null,
    provenance: all.map(path => { const bytes = readFileSync(path); return { path, bytes: bytes.length, sha256: digest(bytes) } })
  }
  verify(archive)
  writeFileSync(output, JSON.stringify(archive, null, 2) + '\n')
}

